export const templates = {"admin_referral":"<div class=\"page-head\">\n    <div>\n        <h1 class=\"page-title\">Referral codes</h1>\n        <p class=\"page-sub\">A code lets one person create a panel account.</p>\n    </div>\n</div>\n\n{{> msgStatus}}\n\n<div class=\"grid-split\">\n<section class=\"card\">\n    <div class=\"card-head\">\n        <div class=\"tile\">{{icon \"ticket\"}}</div>\n        <div><h2 class=\"card-title\">New code</h2><div class=\"card-sub\">Single use</div></div>\n    </div>\n<form method=\"post\" action=\"/admin/create-referral\" class=\"form\" novalidate data-busy-form>\n    <div class=\"field {{#if errors.accLevel}}invalid{{/if}}\">\n        <label class=\"label\" for=\"accLevel\">Role</label>\n        {{{selects.accLevel}}}\n        {{#if errors.accLevel}}<div class=\"error\">{{icon \"circle-alert\"}}<span>{{errors.accLevel}}</span></div>{{/if}}\n    </div>\n    <div class=\"field {{#if errors.accExpire}}invalid{{/if}}\">\n        <label class=\"label\" for=\"accExpire\">Account lasts</label>\n        {{{selects.accExpire}}}\n        {{#if errors.accExpire}}<div class=\"error\">{{icon \"circle-alert\"}}<span>{{errors.accExpire}}</span></div>{{/if}}\n    </div>\n    <div class=\"field {{#if errors.set_saldo}}invalid{{/if}}\">\n        <label class=\"label\" for=\"set_saldo\">Starting balance (₹)</label>\n        <div class=\"input-wrap\">{{icon \"wallet\" \"lead\"}}\n        <input type=\"number\" class=\"input\" name=\"set_saldo\" id=\"set_saldo\" min=\"0\" max=\"99999\" step=\"1\" inputmode=\"numeric\" required value=\"{{#if old.set_saldo}}{{old.set_saldo}}{{else}}0{{/if}}\"></div>\n        {{#if errors.set_saldo}}<div class=\"error\">{{icon \"circle-alert\"}}<span>{{errors.set_saldo}}</span></div>{{else}}<div class=\"hint\">{{#if unlimited}}Taken from your unlimited balance.{{else}}Taken from your balance (₹{{user.saldoLabel}}).{{/if}}</div>{{/if}}\n    </div>\n    <button type=\"submit\" class=\"btn btn-primary btn-block\" data-busy-label=\"Creating…\">{{icon \"plus\"}}Create code</button>\n</form>\n</section>\n\n<section class=\"card card-flush\">\n    <div class=\"card-head\" style=\"padding-bottom:16px;margin-bottom:0;border-bottom:1px solid var(--border)\">\n        <div class=\"tile teal\">{{icon \"list-filter\"}}</div>\n        <div><h2 class=\"card-title\">Recent codes</h2><div class=\"card-sub\">{{totalCodes}} in total</div></div>\n    </div>\n    <div class=\"table-wrap\">\n        <table class=\"responsive\">\n            <thead><tr><th>Code</th><th>Role</th><th>Balance</th><th>Used by</th></tr></thead>\n            <tbody>\n                {{#each codes}}\n                <tr>\n                    <td class=\"primary-cell\" data-label=\"Code\"><span class=\"keytext\">{{this.referral}}<button type=\"button\" class=\"icon-btn\" data-copy-text=\"{{this.referral}}\" aria-label=\"Copy code {{this.referral}}\" title=\"Copy\">{{icon \"copy\"}}</button></span></td>\n                    <td data-label=\"Role\">{{this.levelName}}</td>\n                    <td data-label=\"Balance\" class=\"num\">{{this.saldoLabel}}</td>\n                    <td data-label=\"Used by\">{{#if this.used_by}}{{this.used_by}}{{else}}<span class=\"status unused\">Available</span>{{/if}}</td>\n                </tr>\n                {{else}}\n                <tr class=\"is-empty\"><td colspan=\"4\"><div class=\"empty\"><div class=\"tile gray\">{{icon \"ticket\"}}</div><b>No codes yet</b>Create one to invite a reseller.</div></td></tr>\n                {{/each}}\n            </tbody>\n        </table>\n    </div>\n</section>\n</div>\n","admin_user_edit":"<div class=\"page-head\">\n    <div class=\"page-head-main\">\n        <a href=\"/admin/manage-users\" class=\"icon-btn lg\" aria-label=\"Back to users\">{{icon \"chevron-left\"}}</a>\n        <div>\n            <h1 class=\"page-title\">Edit user</h1>\n            <p class=\"page-sub\">{{target.displayName}}</p>\n        </div>\n    </div>\n</div>\n\n{{> msgStatus}}\n\n<section class=\"card\" style=\"max-width:760px\">\n    <div class=\"card-head\">\n        <div class=\"avatar\" aria-hidden=\"true\" style=\"width:46px;height:46px;flex-basis:46px;font-size:18px\">{{initial target.fullname target.username}}</div>\n        <div><h2 class=\"card-title\">{{target.username}}</h2><div class=\"card-sub\">{{target.email}}</div></div>\n    </div>\n<form method=\"post\" action=\"/admin/user/{{target.id_users}}\" class=\"form\" novalidate data-busy-form>\n    <input type=\"hidden\" name=\"user_id\" value=\"{{target.id_users}}\">\n    <div class=\"field-row\">\n        <div class=\"field {{#if errors.username}}invalid{{/if}}\">\n            <label class=\"label\" for=\"username\">Username</label>\n            <div class=\"input-wrap\">{{icon \"at-sign\" \"lead\"}}\n            <input type=\"text\" class=\"input\" name=\"username\" id=\"username\" value=\"{{form.username}}\" required minlength=\"4\" maxlength=\"25\" autocomplete=\"off\" autocapitalize=\"none\" spellcheck=\"false\"></div>\n            {{#if errors.username}}<div class=\"error\">{{icon \"circle-alert\"}}<span>{{errors.username}}</span></div>{{else}}<div class=\"hint\">Renaming keeps their keys attached.</div>{{/if}}\n        </div>\n        <div class=\"field {{#if errors.fullname}}invalid{{/if}}\">\n            <label class=\"label\" for=\"fullname\">Name</label>\n            <div class=\"input-wrap\">{{icon \"user\" \"lead\"}}\n            <input type=\"text\" class=\"input\" name=\"fullname\" id=\"fullname\" value=\"{{form.fullname}}\" maxlength=\"155\" autocomplete=\"off\"></div>\n            {{#if errors.fullname}}<div class=\"error\">{{icon \"circle-alert\"}}<span>{{errors.fullname}}</span></div>{{/if}}\n        </div>\n    </div>\n    <div class=\"field-row\">\n        <div class=\"field {{#if errors.level}}invalid{{/if}}\">\n            <label class=\"label\" for=\"level\">Role</label>\n            {{{selects.level}}}\n            {{#if errors.level}}<div class=\"error\">{{icon \"circle-alert\"}}<span>{{errors.level}}</span></div>{{/if}}\n        </div>\n        <div class=\"field {{#if errors.status}}invalid{{/if}}\">\n            <label class=\"label\" for=\"status\">Status</label>\n            {{{selects.status}}}\n            {{#if errors.status}}<div class=\"error\">{{icon \"circle-alert\"}}<span>{{errors.status}}</span></div>{{/if}}\n        </div>\n    </div>\n    <div class=\"field-row\">\n        <div class=\"field {{#if errors.saldo}}invalid{{/if}}\">\n            <label class=\"label\" for=\"saldo\">Balance (₹)</label>\n            <div class=\"input-wrap\">{{icon \"wallet\" \"lead\"}}\n            <input type=\"number\" class=\"input\" name=\"saldo\" id=\"saldo\" value=\"{{form.saldo}}\" min=\"0\" max=\"999999999\" step=\"1\" inputmode=\"numeric\" required></div>\n            {{#if errors.saldo}}<div class=\"error\">{{icon \"circle-alert\"}}<span>{{errors.saldo}}</span></div>{{/if}}\n        </div>\n        <div class=\"field {{#if errors.uplink}}invalid{{/if}}\">\n            <label class=\"label\" for=\"uplink\">Invited by</label>\n            <div class=\"input-wrap\">{{icon \"user-plus\" \"lead\"}}\n            <input type=\"text\" class=\"input\" name=\"uplink\" id=\"uplink\" value=\"{{form.uplink}}\" required maxlength=\"25\" autocomplete=\"off\"></div>\n            {{#if errors.uplink}}<div class=\"error\">{{icon \"circle-alert\"}}<span>{{errors.uplink}}</span></div>{{/if}}\n        </div>\n    </div>\n    <div class=\"field {{#if errors.expiration}}invalid{{/if}}\">\n        <label class=\"label\" for=\"expiration\">Account expires (IST)</label>\n        <div class=\"input-wrap\">{{icon \"calendar\" \"lead\"}}\n        <input type=\"text\" class=\"input mono\" name=\"expiration\" id=\"expiration\" value=\"{{form.expiration}}\" placeholder=\"Never\" autocomplete=\"off\"></div>\n        {{#if errors.expiration}}<div class=\"error\">{{icon \"circle-alert\"}}<span>{{errors.expiration}}</span></div>{{else}}<div class=\"hint\">YYYY-MM-DD HH:MM:SS, Indian time (IST), or empty for never.</div>{{/if}}\n    </div>\n    <button type=\"submit\" class=\"btn btn-primary btn-block\" data-busy-label=\"Saving…\">{{icon \"check\"}}Save changes</button>\n</form>\n</section>\n","admin_users":"<div class=\"page-head\">\n    <div>\n        <h1 class=\"page-title\">Users</h1>\n        <p class=\"page-sub\">{{userList.length}} accounts</p>\n    </div>\n    <div class=\"page-actions\">\n        <a href=\"/admin/create-referral\" class=\"btn btn-primary\">{{icon \"user-plus\"}}Invite with a code</a>\n    </div>\n</div>\n\n{{> msgStatus}}\n\n<section class=\"card card-flush\">\n    <div class=\"toolbar\">\n        <div class=\"input-wrap\">\n            {{icon \"search\" \"lead\"}}\n            <input type=\"search\" class=\"input\" placeholder=\"Search users\" aria-label=\"Search users\" data-filter-table=\"users-table\" autocomplete=\"off\">\n        </div>\n    </div>\n    <div class=\"table-wrap\">\n        <table class=\"responsive\" id=\"users-table\">\n            <thead><tr><th>User</th><th>Role</th><th>Balance</th><th>Status</th><th>Expires</th><th>Invited by</th><th class=\"actions-cell\"><span class=\"sr-only\">Actions</span></th></tr></thead>\n            <tbody>\n                {{#each userList}}\n                <tr>\n                    <td class=\"primary-cell\" data-label=\"User\"><div class=\"cell-user\"><div class=\"avatar\" aria-hidden=\"true\">{{initial this.username}}</div><div><strong>{{this.username}}</strong><div class=\"cell-sub\">{{this.email}}</div></div></div></td>\n                    <td data-label=\"Role\">{{this.levelName}}</td>\n                    <td data-label=\"Balance\" class=\"num\">{{this.saldoLabel}}</td>\n                    <td data-label=\"Status\"><span class=\"status {{#if (eq this.status 1)}}ok{{else}}bad{{/if}}\">{{this.statusName}}</span></td>\n                    <td data-label=\"Expires\">{{this.expiresLabel}}</td>\n                    <td data-label=\"Invited by\">{{this.uplink}}</td>\n                    <td class=\"actions-cell\">\n                        {{#if this.isOwnerRow}}<span class=\"faint row\" style=\"gap:6px;justify-content:flex-end\">{{icon \"crown\" \"i-sm\"}}Owner</span>{{else}}\n                        <span class=\"row-actions\">\n                            <a class=\"icon-btn\" href=\"/admin/user/{{this.id_users}}\" aria-label=\"Edit {{this.username}}\" title=\"Edit\">{{icon \"pencil\"}}</a>\n                            <form method=\"post\" action=\"/admin/user/delete/{{this.id_users}}\" style=\"display:inline\" data-confirm=\"Delete {{this.username}}?\" data-confirm-detail=\"Their keys are deleted too; never-used keys are refunded. This cannot be undone.\">\n                                <button type=\"submit\" class=\"icon-btn danger\" aria-label=\"Delete {{this.username}}\" title=\"Delete\">{{icon \"trash-2\"}}</button>\n                            </form>\n                        </span>\n                        {{/if}}\n                    </td>\n                </tr>\n                {{else}}\n                <tr class=\"is-empty\"><td colspan=\"7\"><div class=\"empty\"><div class=\"tile gray\">{{icon \"users\"}}</div><b>No users yet</b>Invite someone with a referral code.</div></td></tr>\n                {{/each}}\n            </tbody>\n        </table>\n    </div>\n</section>\n","api_docs":"<div class=\"docs\">\n    <div class=\"page-head\">\n        <div>\n            <h1 class=\"page-title\">API docs</h1>\n            <p class=\"page-sub\">Key management for your website or Telegram bot.</p>\n        </div>\n        <div class=\"page-actions\"><a href=\"/api-keys\" class=\"btn btn-primary\">{{icon \"key-square\"}}Manage API keys</a></div>\n    </div>\n    {{> msgStatus}}\n    <section class=\"card\">\n        <div class=\"card-head\">\n            <div class=\"tile purple\">{{icon \"book-open\"}}</div>\n            <div><h2 class=\"card-title\">Overview</h2></div>\n        </div>\n        <p class=\"muted\">Use a <strong>personal API key</strong> to create, list, read, update,\n        reset and delete <strong>licence keys</strong> from your own website or Telegram bot.\n        Creating a key through the API charges your saldo exactly like the panel does.</p>\n        <p class=\"doc-note\" style=\"margin-top:14px\">This API is <strong>only for keys</strong>. It cannot change the mod name,\n        status text, floating text, features, maintenance mode or any other server setting.\n        For the loader / mod side, see <a href=\"/docs\">Integration docs</a>.</p>\n    </section>\n\n    <div class=\"card\">\n        <div class=\"doc-section\">\n            <h2>1. Get an API key</h2>\n            <p>Log in to the panel, open <a href=\"/api-keys\">API keys</a>, give the key a name (for example\n            <span class=\"doc-inline\">my-telegram-bot</span>) and press <strong>Create API key</strong>.\n            The token starts with <span class=\"doc-inline\">amk_</span> and is shown <strong>once</strong> — copy it immediately.\n            Only its SHA-256 hash is stored, so it cannot be recovered later. You can revoke or delete it at any time.</p>\n        </div>\n\n        <div class=\"doc-section\">\n            <h2>2. Base URL + authentication</h2>\n            <code class=\"doc-url\">{{apiBase}}/api/v1</code>\n            <p>Send the token on <strong>every</strong> request as the <span class=\"doc-inline\">X-API-Key</span> header\n            (<span class=\"doc-inline\">Authorization: Bearer &lt;token&gt;</span> also works). No cookies, no session, no CSRF token.\n            CORS is open, so a browser site on another domain can call it directly.</p>\n            <pre class=\"doc-code\"><code>X-API-Key: amk_YOUR_TOKEN_HERE\nContent-Type: application/json</code></pre>\n            <p>Missing or revoked key → <span class=\"doc-inline\">401</span>. A key whose owner is banned or expired → <span class=\"doc-inline\">403</span>.</p>\n        </div>\n\n        <div class=\"doc-section\">\n            <h2>3. Response shape</h2>\n            <pre class=\"doc-code\"><code>// success\n{ \"ok\": true, \"keys\": [ ... ], \"total\": 2, \"limit\": 50, \"offset\": 0 }\n\n// failure\n{ \"ok\": false, \"error\": { \"code\": \"insufficient_balance\", \"message\": \"Insufficient balance\" } }</code></pre>\n            <p>Always check <span class=\"doc-inline\">ok</span> and the HTTP status. Errors are JSON, never HTML.</p>\n        </div>\n    </div>\n\n    <div class=\"card\">\n        <div class=\"doc-section\">\n            <h2>4. Endpoints</h2>\n            <div class=\"table-scroll\">\n                <table class=\"responsive\">\n                    <thead><tr><th>Method</th><th>Path</th><th>What it does</th></tr></thead>\n                    <tbody>\n                        <tr><td>GET</td><td><span class=\"doc-inline\">/api/v1</span></td><td>Endpoint index + your API key name</td></tr>\n                        <tr><td>GET</td><td><span class=\"doc-inline\">/api/v1/me</span></td><td>Account saldo / level and API key info</td></tr>\n                        <tr><td>GET</td><td><span class=\"doc-inline\">/api/v1/pricing</span></td><td>Available durations and price per device</td></tr>\n                        <tr><td>GET</td><td><span class=\"doc-inline\">/api/v1/keys</span></td><td>List your keys (pagination + filters)</td></tr>\n                        <tr><td>POST</td><td><span class=\"doc-inline\">/api/v1/keys</span></td><td><strong>Create keys</strong> — charges saldo</td></tr>\n                        <tr><td>GET</td><td><span class=\"doc-inline\">/api/v1/keys/{user_key}</span></td><td>One key with its device list</td></tr>\n                        <tr><td>POST / PATCH</td><td><span class=\"doc-inline\">/api/v1/keys/{user_key}</span></td><td>Update devices / duration / game / status / device list (free)</td></tr>\n                        <tr><td>POST</td><td><span class=\"doc-inline\">/api/v1/keys/{user_key}/reset</span></td><td>Clear all bound devices</td></tr>\n                        <tr><td>DELETE</td><td><span class=\"doc-inline\">/api/v1/keys/{user_key}</span></td><td>Delete a key</td></tr>\n                    </tbody>\n                </table>\n            </div>\n            <p style=\"margin-top:12px\">You can only see and manage keys <strong>your account created</strong>.\n            List filters: <span class=\"doc-inline\">?limit=50&amp;offset=0&amp;game=PUBG&amp;status=1</span>.</p>\n        </div>\n\n        <div class=\"doc-section\">\n            <h2>5. Create a key (curl)</h2>\n            <pre class=\"doc-code\"><code>curl -sS -X POST {{apiBase}}/api/v1/keys \\\n  -H 'X-API-Key: amk_YOUR_TOKEN_HERE' \\\n  -H 'Content-Type: application/json' \\\n  -d '{\"game\":\"PUBG\",\"duration\":24,\"max_devices\":1}'\n</code></pre>\n            <p>Body fields: <span class=\"doc-inline\">game</span> (default <span class=\"doc-inline\">PUBG</span>),\n            <span class=\"doc-inline\">duration</span> (hours: 2, 5, 24, 72, 168, 336, 720),\n            <span class=\"doc-inline\">max_devices</span> (1–100), optional <span class=\"doc-inline\">count</span> (1–100)\n            and optional <span class=\"doc-inline\">custom_key</span> (4–6 letters or digits; replaces the random ending, so\n            <span class=\"doc-inline\">count</span> must be 1).</p>\n            <p>Every key looks like <span class=\"doc-inline\">USERNAME-DURATION-RANDOM</span>, always upper case:\n            <span class=\"doc-inline\">ANOY-7D-GKFHJ</span>. Durations are written as <span class=\"doc-inline\">2H 5H 1D 3D 7D 14D 30D</span>.\n            The Owner account has an unlimited balance and is never charged.</p>\n            <pre class=\"doc-code\"><code>{\n  \"ok\": true,\n  \"keys\": [\n    {\n      \"id\": 3, \"user_key\": \"ANOY-1D-AB3DE\", \"game\": \"PUBG\",\n      \"duration\": 24, \"max_devices\": 1, \"status\": 1,\n      \"devices\": [], \"device_count\": 0, \"expired_date\": null,\n      \"created_at\": \"2026-11-05T10:30:00.000Z\", \"updated_at\": \"2026-11-05T10:30:00.000Z\"\n    }\n  ],\n  \"count\": 1, \"price\": 80, \"currency\": \"INR\",\n  \"saldo_before\": 2147384644, \"saldo_after\": 2147384564, \"charged\": 80\n}</code></pre>\n            <p class=\"doc-note\"><strong>Saldo rule:</strong> <span class=\"doc-inline\">price = price_per_device(duration) × max_devices × count</span>. Every key is charged.\n            The debit and all key inserts run in one database transaction: if anything fails, no keys are created and nothing is charged.\n            Repeating the same <span class=\"doc-inline\">request_id</span> returns the original result instead of charging twice.\n            Insufficient balance → <span class=\"doc-inline\">402 insufficient_balance</span> and nothing is created.</p>\n        </div>\n\n        <div class=\"doc-section\">\n            <h2>6. List / read / update / reset / delete</h2>\n            <pre class=\"doc-code\"><code># list\ncurl -sS {{apiBase}}/api/v1/keys -H 'X-API-Key: amk_YOUR_TOKEN_HERE'\n\n# read one\ncurl -sS {{apiBase}}/api/v1/keys/ANOY-1D-AB3DE -H 'X-API-Key: amk_YOUR_TOKEN_HERE'\n\n# update (POST or PATCH)\ncurl -sS -X PATCH {{apiBase}}/api/v1/keys/ANOY-1D-AB3DE \\\n  -H 'X-API-Key: amk_YOUR_TOKEN_HERE' -H 'Content-Type: application/json' \\\n  -d '{\"max_devices\":3,\"status\":1}'\n\n# clear bound devices\ncurl -sS -X POST {{apiBase}}/api/v1/keys/ANOY-1D-AB3DE/reset \\\n  -H 'X-API-Key: amk_YOUR_TOKEN_HERE'\n\n# delete\ncurl -sS -X DELETE {{apiBase}}/api/v1/keys/ANOY-1D-AB3DE \\\n  -H 'X-API-Key: amk_YOUR_TOKEN_HERE'</code></pre>\n        </div>\n\n        <div class=\"doc-section\">\n            <h2>7. JavaScript fetch example</h2>\n            <pre class=\"doc-code\"><code>const BASE = \"{{apiBase}}/api/v1\";\nconst TOKEN = \"amk_YOUR_TOKEN_HERE\";\n\nasync function api(path, options = {}) {\n  const r = await fetch(BASE + path, {\n    ...options,\n    headers: { \"X-API-Key\": TOKEN, \"Content-Type\": \"application/json\", ...options.headers }\n  });\n  const data = await r.json();\n  if (!data.ok) throw new Error(data.error.code + \": \" + data.error.message);\n  return data;\n}\n\nconst made = await api(\"/keys\", {\n  method: \"POST\",\n  body: JSON.stringify({ game: \"PUBG\", duration: 24, max_devices: 1 })\n});\nconsole.log(made.keys[0].user_key, \"charged\", made.price);</code></pre>\n        </div>\n\n        <div class=\"doc-section\">\n            <h2>8. Error codes</h2>\n            <div class=\"table-scroll\">\n                <table class=\"responsive\">\n                    <thead><tr><th>HTTP</th><th>code</th><th>Meaning</th></tr></thead>\n                    <tbody>\n                        <tr><td>401</td><td><span class=\"doc-inline\">missing_api_key</span>, <span class=\"doc-inline\">invalid_api_key</span></td><td>No key, or revoked/unknown key</td></tr>\n                        <tr><td>403</td><td><span class=\"doc-inline\">account_inactive</span>, <span class=\"doc-inline\">account_expired</span></td><td>Key owner account is blocked or expired</td></tr>\n                        <tr><td>400</td><td><span class=\"doc-inline\">invalid_request</span></td><td>Bad parameters or no updatable field</td></tr>\n                        <tr><td>402</td><td><span class=\"doc-inline\">insufficient_balance</span></td><td>Not enough saldo for the requested keys</td></tr>\n                        <tr><td>404</td><td><span class=\"doc-inline\">key_not_found</span>, <span class=\"doc-inline\">not_found</span></td><td>Key does not exist or is not yours</td></tr>\n                        <tr><td>405</td><td><span class=\"doc-inline\">method_not_allowed</span></td><td>Wrong HTTP verb for the path</td></tr>\n                        <tr><td>409</td><td><span class=\"doc-inline\">key_exists</span>, <span class=\"doc-inline\">balance_conflict</span></td><td>Custom key taken, or concurrent balance change (retry)</td></tr>\n                    </tbody>\n                </table>\n            </div>\n        </div>\n\n        <div class=\"doc-section\">\n            <h2>9. Good practice</h2>\n            <p>Keep the token server-side (bot backend, serverless function), never in public frontend source.\n            Use HTTPS, one key per project so you can revoke it independently, and check\n            <span class=\"doc-inline\">/api/v1/me</span> before a create to show the current balance.\n            Full reference: <span class=\"doc-inline\">API.md</span> in the repo.</p>\n        </div>\n    </div>\n</div>\n","api_keys":"<div class=\"page-head\">\n    <div>\n        <h1 class=\"page-title\">API keys</h1>\n        <p class=\"page-sub\">Let your website or bot create and manage licence keys.</p>\n    </div>\n    <div class=\"page-actions\">\n        <a href=\"/api-docs\" class=\"btn btn-secondary\">{{icon \"book-open\"}}Read the docs</a>\n    </div>\n</div>\n\n{{> msgStatus}}\n\n{{#if flash.apiKeyPlain}}\n<section class=\"card highlight keys-out\" style=\"margin-bottom:20px\">\n    <div class=\"card-head\">\n        <div class=\"tile green\">{{icon \"circle-check\"}}</div>\n        <div><h2 class=\"card-title\">Your new API key</h2><div class=\"card-sub\">Shown once. Anyone with it can spend your balance.</div></div>\n        <span class=\"spacer\"></span>\n        <button type=\"button\" class=\"btn btn-primary btn-sm\" data-copy-target=\"new-api-key\">{{icon \"copy\"}}Copy</button>\n    </div>\n    <input type=\"text\" class=\"input mono\" id=\"new-api-key\" value=\"{{flash.apiKeyPlain}}\" readonly aria-label=\"New API key\">\n</section>\n{{/if}}\n\n<div class=\"grid-split wide-list\">\n<section class=\"card\">\n    <div class=\"card-head\">\n        <div class=\"tile purple\">{{icon \"key-square\"}}</div>\n        <div><h2 class=\"card-title\">New API key</h2><div class=\"card-sub\">Uses your balance and keys</div></div>\n    </div>\n    <form method=\"post\" action=\"/api-keys\" class=\"form\" data-busy-form>\n        <input type=\"hidden\" name=\"action\" value=\"create\">\n        <div class=\"field\">\n            <label class=\"label\" for=\"api-key-name\">Name</label>\n            <div class=\"input-wrap\">{{icon \"tag\" \"lead\"}}\n            <input type=\"text\" class=\"input\" name=\"name\" id=\"api-key-name\" required maxlength=\"80\" placeholder=\"my-telegram-bot\" autocomplete=\"off\"></div>\n            <div class=\"hint\">Only for you, to recognise the key later.</div>\n        </div>\n        <button type=\"submit\" class=\"btn btn-primary btn-block\" data-busy-label=\"Creating…\">{{icon \"plus\"}}Create API key</button>\n    </form>\n</section>\n\n<section class=\"card card-flush\">\n    <div class=\"card-head\" style=\"padding-bottom:16px;margin-bottom:0;border-bottom:1px solid var(--border)\">\n        <div class=\"tile teal\">{{icon \"code-xml\"}}</div>\n        <div><h2 class=\"card-title\">Your keys</h2><div class=\"card-sub\">Send as the X-API-Key header</div></div>\n    </div>\n    <div class=\"table-wrap\">\n        <table class=\"responsive\">\n            <thead><tr><th>Name</th><th>Key</th><th>Status</th><th>Last used</th><th class=\"actions-cell\"><span class=\"sr-only\">Actions</span></th></tr></thead>\n            <tbody>\n                {{#each apiKeys}}\n                <tr>\n                    <td class=\"primary-cell\" data-label=\"Name\">{{this.name}}</td>\n                    <td data-label=\"Key\"><span class=\"keytext\">{{this.key_prefix}}…{{this.key_last4}}</span></td>\n                    <td data-label=\"Status\"><span class=\"status {{#if (eq this.status 1)}}ok{{else}}bad{{/if}}\">{{this.statusLabel}}</span></td>\n                    <td data-label=\"Last used\">{{this.usedLabel}}</td>\n                    <td class=\"actions-cell\"><span class=\"row-actions\">\n                        {{#if (eq this.status 1)}}\n                        <form method=\"post\" action=\"/api-keys\" style=\"display:inline\" data-confirm=\"Revoke {{this.name}}?\" data-confirm-detail=\"Apps using it stop working immediately.\">\n                            <input type=\"hidden\" name=\"action\" value=\"revoke\"><input type=\"hidden\" name=\"id\" value=\"{{this.id}}\">\n                            <button type=\"submit\" class=\"icon-btn\" aria-label=\"Revoke {{this.name}}\" title=\"Revoke\">{{icon \"ban\"}}</button>\n                        </form>\n                        {{/if}}\n                        <form method=\"post\" action=\"/api-keys\" style=\"display:inline\" data-confirm=\"Delete {{this.name}}?\" data-confirm-detail=\"This cannot be undone.\">\n                            <input type=\"hidden\" name=\"action\" value=\"delete\"><input type=\"hidden\" name=\"id\" value=\"{{this.id}}\">\n                            <button type=\"submit\" class=\"icon-btn danger\" aria-label=\"Delete {{this.name}}\" title=\"Delete\">{{icon \"trash-2\"}}</button>\n                        </form>\n                    </span></td>\n                </tr>\n                {{else}}\n                <tr class=\"is-empty\"><td colspan=\"5\"><div class=\"empty\"><div class=\"tile gray\">{{icon \"key-square\"}}</div><b>No API keys yet</b>Create one to connect a bot or website.</div></td></tr>\n                {{/each}}\n            </tbody>\n        </table>\n    </div>\n</section>\n</div>\n","app_update":"<div class=\"page-head\">\n    <div>\n        <h1 class=\"page-title\">App update</h1>\n        <p class=\"page-sub\">Publish a new Anoy app (APK). Phones check this on the splash screen, before the library update.</p>\n    </div>\n</div>\n\n{{> msgStatus}}\n\n<section class=\"card\" style=\"margin-bottom:20px\" id=\"app-current\">\n    <div class=\"hero\">\n        <div class=\"tile tile-lg\">{{icon \"smartphone\"}}</div>\n        <div style=\"flex:1;min-width:180px\">\n            <div class=\"hero-label\">Published app version</div>\n            <div class=\"hero-value mono\">{{#if appRelease}}{{appRelease.version_name}}{{else}}—{{/if}}</div>\n        </div>\n        <div class=\"list\" style=\"min-width:240px;flex:0 1 380px\">\n            <div class=\"list-row\"><span class=\"lr-label\">{{icon \"hash\" \"i-sm\"}}Version code</span><span class=\"lr-value mono\">{{#if appRelease}}{{appRelease.version_code}}{{else}}—{{/if}}</span></div>\n            <div class=\"list-row\"><span class=\"lr-label\">{{icon \"shield\" \"i-sm\"}}Type</span><span class=\"lr-value\">{{#if appRelease}}{{#if appRelease.mandatory}}<span class=\"status warn\">Mandatory</span>{{else}}Normal{{/if}}{{else}}<span class=\"status warn\">Nothing published</span>{{/if}}</span></div>\n            <div class=\"list-row wrap stack-sm\"><span class=\"lr-label\">{{icon \"clock\" \"i-sm\"}}Published</span><span class=\"lr-value\">{{#if appRelease}}{{appRelease.publishedLabel}} · {{appRelease.published_by}}{{else}}—{{/if}}</span></div>\n        </div>\n    </div>\n    {{#if appRelease}}\n    <div class=\"card-foot\">\n        <a href=\"{{appRelease.apk_url}}\" class=\"btn btn-secondary btn-sm\" rel=\"noopener noreferrer\" target=\"_blank\">{{icon \"download\" \"i-sm\"}}Test the APK link</a>\n        <span class=\"hint\" style=\"margin:0\" id=\"app-current-line\">Current update: <span class=\"mono\">{{appRelease.version_name}} ({{appRelease.version_code}})</span> ·</span>\n        <button type=\"button\" class=\"btn btn-danger btn-sm\" id=\"app-remove\">{{icon \"x\" \"i-sm\"}}Remove</button>\n    </div>\n    {{/if}}\n</section>\n\n<section class=\"card publish-card\" id=\"app-publish\">\n    <div class=\"card-head\">\n        <div class=\"tile\">{{icon \"circle-arrow-up\"}}</div>\n        <div><h2 class=\"card-title\">Publish an app update</h2><div class=\"card-sub\">A phone updates when this version code is higher than its own.</div></div>\n    </div>\n    <form id=\"app-form\" class=\"form\" novalidate>\n        <div class=\"field\">\n            <div style=\"display:flex;gap:10px;flex-wrap:wrap;align-items:center\">\n                <button type=\"button\" class=\"btn btn-secondary btn-sm\" id=\"app-latest\">{{icon \"download\" \"i-sm\"}}Use latest build</button>\n                <span class=\"hint\" style=\"margin:0\" id=\"app-latest-result\" aria-live=\"polite\">Fills the version and APK link from the newest GitHub release. You can still edit them.</span>\n            </div>\n        </div>\n        <div class=\"field-row\">\n            <div class=\"field\" data-field=\"version_name\">\n                <label class=\"label\" for=\"app-version-name\">Version name</label>\n                <div class=\"input-wrap\">{{icon \"tag\" \"lead\"}}\n                <input type=\"text\" class=\"input mono\" name=\"version_name\" id=\"app-version-name\" maxlength=\"32\" placeholder=\"2.2.0\" autocomplete=\"off\" spellcheck=\"false\"></div>\n                <div class=\"error\" hidden></div>\n            </div>\n            <div class=\"field\" data-field=\"version_code\">\n                <label class=\"label\" for=\"app-version-code\">Version code</label>\n                <div class=\"input-wrap\">{{icon \"hash\" \"lead\"}}\n                <input type=\"number\" class=\"input mono\" name=\"version_code\" id=\"app-version-code\" min=\"1\" step=\"1\" inputmode=\"numeric\" value=\"{{suggestedCode}}\" placeholder=\"8\"></div>\n                <div class=\"hint\">{{#if appRelease}}Current: {{appRelease.version_code}}. Must be higher.{{else}}Whole number, from the APK's build.{{/if}}</div>\n                <div class=\"error\" hidden></div>\n            </div>\n        </div>\n        <div class=\"field\" data-field=\"apk_url\">\n            <label class=\"label\" for=\"app-apk-url\">APK link (https)</label>\n            <div class=\"input-wrap\">{{icon \"link\" \"lead\"}}\n            <input type=\"url\" class=\"input\" name=\"apk_url\" id=\"app-apk-url\" placeholder=\"https://github.com/…/releases/download/…/Anoy.apk\" autocomplete=\"off\" spellcheck=\"false\" inputmode=\"url\"></div>\n            <div class=\"hint\">The GitHub release asset link. It is checked before publishing, and the APK must be signed with the same key as the installed app.</div>\n            <div class=\"error\" hidden></div>\n        </div>\n        <div class=\"field\" data-field=\"changelog\">\n            <label class=\"label\" for=\"app-changelog\">Changelog</label>\n            <textarea class=\"input\" name=\"changelog\" id=\"app-changelog\" maxlength=\"2000\" rows=\"5\" placeholder=\"What changed, one point per line\"></textarea>\n            <div class=\"error\" hidden></div>\n        </div>\n        <div class=\"field\">\n            <span class=\"label\">Type</span>\n            <div class=\"segmented block\" role=\"radiogroup\" aria-label=\"Update type\">\n                <label><input type=\"radio\" name=\"type\" value=\"normal\" checked><span>{{icon \"circle-check\" \"i-sm\"}}Normal</span></label>\n                <label><input type=\"radio\" name=\"type\" value=\"mandatory\"><span>{{icon \"triangle-alert\" \"i-sm\"}}Mandatory</span></label>\n            </div>\n            <div class=\"hint\">Normal shows “Not now”. Mandatory has only “Update now”.</div>\n        </div>\n        <button type=\"submit\" class=\"btn btn-primary btn-block\" id=\"app-submit\">{{icon \"upload\"}}Publish app update</button>\n        <div class=\"hint\">Phones see changes within about a minute.</div>\n        <div id=\"app-result\" aria-live=\"polite\"></div>\n    </form>\n</section>\n\n\n<script>\n(function () {\n    'use strict';\n    var byId = function (id) { return document.getElementById(id); };\n    var form = byId('app-form'), button = byId('app-submit'), result = byId('app-result');\n\n    function say(text, ok) {\n        result.textContent = '';\n        var p = document.createElement('p');\n        p.className = ok ? 'hint' : 'error';\n        p.style.marginTop = '12px';\n        p.textContent = text;\n        result.appendChild(p);\n    }\n    function fieldError(name, text) {\n        var field = form.querySelector('[data-field=\"' + name + '\"]');\n        if (!field) return;\n        var box = field.querySelector('.error');\n        field.classList.toggle('invalid', !!text);\n        box.hidden = !text;\n        box.textContent = text || '';\n    }\n    function clearErrors() {\n        ['version_name', 'version_code', 'apk_url', 'changelog'].forEach(function (n) { fieldError(n, ''); });\n        result.textContent = '';\n    }\n    function busy(btn, on, label) {\n        if (on) { btn.dataset.html = btn.innerHTML; btn.textContent = label; btn.disabled = true; }\n        else { if (btn.dataset.html) btn.innerHTML = btn.dataset.html; btn.disabled = false; }\n    }\n    function httpsUrl(u) {\n        if (!/^https:\\/\\/\\S+$/i.test(u)) return false;\n        try { return new URL(u).protocol === 'https:'; } catch (e) { return false; }\n    }\n    function post(payload) {\n        return fetch('/app-update', {\n            method: 'POST', credentials: 'same-origin',\n            headers: { 'Content-Type': 'application/json', Accept: 'application/json' },\n            body: JSON.stringify(payload)\n        }).then(function (r) {\n            return r.json().catch(function () { return null; }).then(function (data) {\n                if (r.ok && data && data.ok) return data;\n                var err = new Error((data && data.error) || ('The server answered ' + r.status + '. Nothing was changed.'));\n                err.errors = data && data.errors;\n                throw err;\n            });\n        });\n    }\n\n    form.addEventListener('submit', function (e) {\n        e.preventDefault();\n        if (button.disabled) return;\n        clearErrors();\n        var data = {\n            action: 'publish',\n            version_name: byId('app-version-name').value.trim(),\n            version_code: byId('app-version-code').value.trim(),\n            apk_url: byId('app-apk-url').value.trim(),\n            changelog: byId('app-changelog').value,\n            type: (form.querySelector('input[name=type]:checked') || {}).value || 'normal'\n        };\n        var bad = false;\n        if (!/^[0-9A-Za-z][0-9A-Za-z._+-]{0,31}$/.test(data.version_name)) { fieldError('version_name', 'Enter a version name like 2.2.0.'); bad = true; }\n        if (!/^\\d{1,10}$/.test(data.version_code) || Number(data.version_code) < 1) { fieldError('version_code', 'Enter the version code as a whole number, like 8.'); bad = true; }\n        if (!data.apk_url) { fieldError('apk_url', 'Enter the https:// link to the APK.'); bad = true; }\n        else if (!httpsUrl(data.apk_url)) { fieldError('apk_url', 'The APK link must be a full https:// address (http:// is not allowed).'); bad = true; }\n        if (!data.changelog.trim()) { fieldError('changelog', 'Write a short changelog: it is shown on the update screen.'); bad = true; }\n        if (bad) return say('Fix the highlighted fields. Nothing was published.');\n        busy(button, true, 'Checking the link…');\n        post(data).then(function (r) {\n            say('App ' + r.version_name + ' (' + r.version_code + ') is live. Reloading…', true);\n            setTimeout(function () { location.reload(); }, 1200);\n        }).catch(function (err) {\n            if (err.errors) Object.keys(err.errors).forEach(function (k) { fieldError(k, err.errors[k]); });\n            say(err.message || 'Publishing failed. Nothing was changed.');\n            busy(button, false);\n        });\n    });\n\n    var remove = byId('app-remove');\n    if (remove) remove.addEventListener('click', function () {\n        if (remove.disabled) return;\n        if (!window.confirm('Remove the current app update? Phones will stop offering it.')) return;\n        busy(remove, true, 'Removing…');\n        post({ action: 'remove' }).then(function () { location.reload(); }).catch(function (err) {\n            say(err.message || 'Could not remove the update.');\n            busy(remove, false);\n        });\n    });\n\n    // \"Use latest build\": the newest anoy-v<name>-<code> GitHub release fills the fields.\n    var latest = byId('app-latest'), latestResult = byId('app-latest-result');\n    latest.addEventListener('click', function () {\n        if (latest.disabled) return;\n        busy(latest, true, 'Looking up…');\n        fetch('/app-update/latest-build', { credentials: 'same-origin', headers: { Accept: 'application/json' } })\n            .then(function (r) { return r.json().catch(function () { return null; }).then(function (d) { return { r: r, d: d }; }); })\n            .then(function (x) {\n                busy(latest, false);\n                if (!x.r.ok || !x.d || !x.d.ok) {\n                    latestResult.className = 'error';\n                    latestResult.textContent = (x.d && x.d.error) || ('Lookup failed (HTTP ' + x.r.status + ').');\n                    return;\n                }\n                byId('app-version-name').value = x.d.version_name;\n                byId('app-version-code').value = x.d.version_code;\n                byId('app-apk-url').value = x.d.apk_url;\n                ['version_name', 'version_code', 'apk_url'].forEach(function (n) { fieldError(n, ''); });\n                latestResult.className = 'hint';\n                latestResult.textContent = 'Filled from ' + x.d.tag + '. Add a changelog, then publish.';\n            })\n            .catch(function () {\n                busy(latest, false);\n                latestResult.className = 'error';\n                latestResult.textContent = 'Could not look up the latest build. Enter the fields by hand.';\n            });\n    });\n})();\n</script>\n","dashboard":"<div class=\"page-head\">\n    <div>\n        <h1 class=\"page-title\">Dashboard</h1>\n        <p class=\"page-sub\">Signed in as {{user.displayName}} · {{user.levelName}}</p>\n    </div>\n    <div class=\"page-actions\">\n        <a href=\"/keys\" class=\"btn btn-secondary\">{{icon \"key-round\"}}All keys</a>\n        <a href=\"/keys/generate\" class=\"btn btn-primary\">{{icon \"plus\"}}Generate keys</a>\n    </div>\n</div>\n\n{{> msgStatus}}\n\n<section class=\"card\" style=\"margin-bottom:20px\">\n    <div class=\"hero\">\n        <div class=\"tile tile-lg\">{{icon \"wallet\"}}</div>\n        <div style=\"flex:1;min-width:200px\">\n            <div class=\"hero-label\">Balance</div>\n            <div class=\"hero-value\">{{#if unlimited}}{{icon \"infinity\"}}Unlimited{{else}}₹{{user.saldoLabel}}{{/if}}</div>\n        </div>\n        <div class=\"list\" style=\"min-width:220px;flex:0 1 300px\">\n            <div class=\"list-row\"><span class=\"lr-label\">{{#if user.isOwner}}{{icon \"crown\" \"i-sm\"}}{{else}}{{icon \"badge-check\" \"i-sm\"}}{{/if}}Role</span><span class=\"lr-value\">{{user.levelName}}</span></div>\n            <div class=\"list-row wrap stack-sm\" id=\"account-expires\"><span class=\"lr-label\">{{icon \"calendar\" \"i-sm\"}}Account expires</span><span class=\"lr-value\">{{#if stats.expiryFormatted}}{{stats.expiryFormatted}}{{else}}Never{{/if}}</span></div>\n        </div>\n    </div>\n</section>\n\n<div class=\"stats\" aria-label=\"Key statistics\">\n    <div class=\"stat\">\n        <div class=\"stat-top\"><span class=\"stat-label\">Total keys</span><span class=\"tile tile-sm\">{{icon \"key-round\"}}</span></div>\n        <div class=\"stat-value\" data-stat=\"keys\">{{stats.keys}}</div>\n        <div class=\"stat-foot\">{{#if user.isOwner}}Across all accounts{{else}}Created by you{{/if}}</div>\n    </div>\n    <div class=\"stat\">\n        <div class=\"stat-top\"><span class=\"stat-label\">In use</span><span class=\"tile tile-sm green\">{{icon \"activity\"}}</span></div>\n        <div class=\"stat-value\" data-stat=\"active\">{{stats.active}}</div>\n        <div class=\"stat-foot\">Running on a device</div>\n    </div>\n    <div class=\"stat\">\n        <div class=\"stat-top\"><span class=\"stat-label\">Unused</span><span class=\"tile tile-sm teal\">{{icon \"sparkles\"}}</span></div>\n        <div class=\"stat-value\" data-stat=\"unused\">{{stats.inactive}}</div>\n        <div class=\"stat-foot\">Ready to hand out</div>\n    </div>\n    <div class=\"stat\">\n        <div class=\"stat-top\"><span class=\"stat-label\">Expired</span><span class=\"tile tile-sm orange\">{{icon \"hourglass\"}}</span></div>\n        <div class=\"stat-value\" data-stat=\"expired\">{{stats.expired}}</div>\n        <div class=\"stat-foot\">Safe to clean up</div>\n    </div>\n</div>\n\n<div class=\"grid-2\">\n    <section class=\"card\">\n        <div class=\"card-head\">\n            <div class=\"tile purple\">{{icon \"user-round\"}}</div>\n            <div><h2 class=\"card-title\">Account</h2><div class=\"card-sub\">Your panel identity</div></div>\n        </div>\n        <div class=\"list\">\n            <div class=\"list-row\"><span class=\"lr-label\">{{icon \"at-sign\" \"i-sm\"}}Username</span><span class=\"lr-value\">{{user.username}}</span></div>\n            <div class=\"list-row\"><span class=\"lr-label\">{{icon \"shield\" \"i-sm\"}}Role</span><span class=\"lr-value\">{{user.levelName}}</span></div>\n            <div class=\"list-row\"><span class=\"lr-label\">{{icon \"wallet\" \"i-sm\"}}Balance</span><span class=\"lr-value\">{{#if unlimited}}Unlimited{{else}}₹{{user.saldoLabel}}{{/if}}</span></div>\n            {{#if user.isAdmin}}<div class=\"list-row\"><span class=\"lr-label\">{{icon \"users\" \"i-sm\"}}{{#if user.isOwner}}Users{{else}}Users you invited{{/if}}</span><span class=\"lr-value\">{{stats.users}}</span></div>{{/if}}\n        </div>\n    </section>\n    <section class=\"card\">\n        <div class=\"card-head\">\n            <div class=\"tile\">{{icon \"zap\"}}</div>\n            <div><h2 class=\"card-title\">Quick actions</h2><div class=\"card-sub\">Jump to what you need</div></div>\n        </div>\n        <div class=\"list\">\n            <a class=\"list-row\" href=\"/keys/generate\"><span class=\"lr-label\"><span class=\"tile tile-sm\">{{icon \"wand-sparkles\"}}</span>Generate keys</span>{{icon \"chevron-right\" \"chev\"}}</a>\n            <a class=\"list-row\" href=\"/keys\"><span class=\"lr-label\"><span class=\"tile tile-sm teal\">{{icon \"key-round\"}}</span>All keys</span>{{icon \"chevron-right\" \"chev\"}}</a>\n            {{#if user.isAdmin}}<a class=\"list-row\" href=\"/server\"><span class=\"lr-label\"><span class=\"tile tile-sm green\">{{icon \"server\"}}</span>Server settings</span>{{icon \"chevron-right\" \"chev\"}}</a>{{/if}}\n            {{#if user.isOwner}}<a class=\"list-row\" href=\"/lib\"><span class=\"lr-label\"><span class=\"tile tile-sm purple\">{{icon \"package\"}}</span>Publish library update</span>{{icon \"chevron-right\" \"chev\"}}</a>{{/if}}\n            <a class=\"list-row\" href=\"/settings\"><span class=\"lr-label\"><span class=\"tile tile-sm gray\">{{icon \"settings\"}}</span>Account settings</span>{{icon \"chevron-right\" \"chev\"}}</a>\n        </div>\n    </section>\n</div>\n","header":"<aside class=\"sidebar\" id=\"sidebar\" aria-label=\"Main navigation\">\n    <a href=\"/dashboard\" class=\"brand\">{{brand}} <small>Panel</small></a>\n    <nav class=\"nav\">\n        <a href=\"/dashboard\" class=\"{{#if navDashboard}}active{{/if}}\">{{icon \"layout-dashboard\"}}<span>Dashboard</span></a>\n        <a href=\"/keys\" class=\"{{#if navKeys}}active{{/if}}\">{{icon \"key-round\"}}<span>Keys</span></a>\n        <a href=\"/keys/generate\" class=\"{{#if navGenerate}}active{{/if}}\">{{icon \"wand-sparkles\"}}<span>Generate keys</span></a>\n        {{#if user.isAdmin}}\n        <div class=\"nav-label\">Manage</div>\n        <a href=\"/server\" class=\"{{#if navServer}}active{{/if}}\">{{icon \"server\"}}<span>Server</span></a>\n        <a href=\"/admin/create-referral\" class=\"{{#if navReferral}}active{{/if}}\">{{icon \"ticket\"}}<span>Referral codes</span></a>\n        <a href=\"/app-update\" class=\"{{#if navAppUpdate}}active{{/if}}\">{{icon \"circle-arrow-up\"}}<span>App update</span></a>\n        {{/if}}\n        {{#if user.isOwner}}\n        <a href=\"/admin/manage-users\" class=\"{{#if navUsers}}active{{/if}}\">{{icon \"users\"}}<span>Users</span></a>\n        <a href=\"/lib\" class=\"{{#if navLib}}active{{/if}}\">{{icon \"package\"}}<span>Library</span></a>\n        {{/if}}\n        <div class=\"nav-label\">Developers</div>\n        <a href=\"/api-keys\" class=\"{{#if navApiKeys}}active{{/if}}\">{{icon \"key-square\"}}<span>API keys</span></a>\n        <a href=\"/api-docs\" class=\"{{#if navApiDocs}}active{{/if}}\">{{icon \"code-xml\"}}<span>API docs</span></a>\n        <a href=\"/docs\" class=\"{{#if navIntegration}}active{{/if}}\">{{icon \"plug-zap\"}}<span>Integration</span></a>\n        <div class=\"nav-label\">Account</div>\n        <a href=\"/settings\" class=\"{{#if navSettings}}active{{/if}}\">{{icon \"settings\"}}<span>Settings</span></a>\n    </nav>\n    {{#if user}}\n    <div class=\"sidebar-foot\">\n        <div class=\"avatar\" aria-hidden=\"true\">{{initial user.fullname user.username}}</div>\n        <div class=\"who-text\">\n            <div class=\"who\">{{user.displayName}}</div>\n            <div class=\"who-sub\">{{#if user.isOwner}}{{icon \"crown\"}}{{else}}{{icon \"badge-check\"}}{{/if}}{{user.levelName}} · {{#if user.unlimited}}Unlimited{{else}}₹{{user.saldoLabel}}{{/if}}</div>\n        </div>\n        <a href=\"/logout\" class=\"icon-btn danger\" aria-label=\"Sign out\" title=\"Sign out\">{{icon \"log-out\"}}</a>\n    </div>\n    {{/if}}\n</aside>\n","integration_docs":"<div class=\"docs\">\n    <div class=\"page-head\">\n        <div>\n            <h1 class=\"page-title\">Integration docs</h1>\n            <p class=\"page-sub\">Connect the loader and mod with one call.</p>\n        </div>\n        <div class=\"page-actions\"><a href=\"/api-docs\" class=\"btn btn-secondary\">{{icon \"book-open\"}}API docs</a></div>\n    </div>\n    {{> msgStatus}}\n    <section class=\"card\">\n        <div class=\"card-head\">\n            <div class=\"tile teal\">{{icon \"plug-zap\"}}</div>\n            <div><h2 class=\"card-title\">Overview</h2></div>\n        </div>\n        <p class=\"muted\">Loader / mod integration: one call does everything —\n        <span class=\"doc-inline\">POST /connect</span>. Below is the connect URL, every response field\n        (mod name, status text, floating text, mod features, expiry), the error text, and simple C++ code.\n        The full reference also lives in <span class=\"doc-inline\">INTEGRATION.md</span> in the repo.</p>\n        <p class=\"doc-note\" style=\"margin-top:14px\">Need to <strong>create, list or delete licence keys</strong> from your\n        own site or Telegram bot? That is a different API with personal API keys — see\n        <a href=\"/api-keys\">API keys</a> and <a href=\"/api-docs\">API docs (key management)</a>.\n        This page is only for the loader / mod side.</p>\n    </section>\n\n    <div class=\"card\">\n        <div class=\"doc-section\">\n            <h2>Base URL</h2>\n            <code class=\"doc-url\">{{apiBase}}</code>\n            <p>Every endpoint below is relative to this host. All loader traffic must use HTTPS.</p>\n        </div>\n\n        <div class=\"doc-section\">\n            <h2>1. Connect URL</h2>\n            <pre class=\"doc-code\"><code>POST {{apiBase}}/connect\nContent-Type: application/x-www-form-urlencoded\n\ngame=PUBG&amp;user_key=ANOY-2H-LYK0Y&amp;serial=DEVICE123</code></pre>\n            <p>GET is also supported for loaders that use a query string:\n            <span class=\"doc-inline\">/connect?game=PUBG&amp;user_key=…&amp;serial=…</span>.\n            <span class=\"doc-inline\">/api/connect</span> is an alias.</p>\n            <div class=\"table-scroll\">\n                <table class=\"responsive\">\n                    <thead><tr><th>Parameter</th><th>Rules</th><th>What it is</th></tr></thead>\n                    <tbody>\n                        <tr><td><span class=\"doc-inline\">game</span></td><td>required, letters / digits / <span class=\"doc-inline\">_</span> / <span class=\"doc-inline\">-</span></td><td>Game the key was generated for (default <span class=\"doc-inline\">PUBG</span>)</td></tr>\n                        <tr><td><span class=\"doc-inline\">user_key</span></td><td>required, 1–36 characters</td><td>Licence key from <span class=\"doc-inline\">/keys</span></td></tr>\n                        <tr><td><span class=\"doc-inline\">serial</span></td><td>required, letters / digits / <span class=\"doc-inline\">_</span> / <span class=\"doc-inline\">-</span></td><td>Stable per-device ID; stored against the key</td></tr>\n                    </tbody>\n                </table>\n            </div>\n        </div>\n\n        <div class=\"doc-section\">\n            <h2>2. curl example</h2>\n            <pre class=\"doc-code\"><code>curl -sS -X POST {{apiBase}}/connect \\\n  -d 'game=PUBG' \\\n  -d 'user_key=ANOY-2H-LYK0Y' \\\n  -d 'serial=DEVICE123'</code></pre>\n        </div>\n\n        <div class=\"doc-section\">\n            <h2>3. Success response</h2>\n            <pre class=\"doc-code\"><code>{\n  \"status\": true,\n  \"data\": {\n    \"real\": \"PUBG-ANOY-2H-LYK0Y-DEVICE123-STATIC_WORDS\",\n    \"token\": \"1aa36c890b3155533de4ed2e09714704\",\n    \"modname\": \"VIP MOD\",\n    \"mod_status\": \"Safe\",\n    \"credit\": \"MOD STATUS :- 100% SAFE\",\n    \"ESP\": \"on\", \"Item\": \"on\", \"AIM\": \"on\", \"SilentAim\": \"on\",\n    \"BulletTrack\": \"on\", \"Floating\": \"on\", \"Memory\": \"on\", \"Setting\": \"on\",\n    \"expired_date\": \"2026-11-05T11:00:20.704Z\",\n    \"EXP\": \"2026-11-05T11:00:20.704Z\",\n    \"exdate\": \"2026-11-05T11:00:20.704Z\",\n    \"device\": 1,\n    \"rng\": 1762333220\n  }\n}</code></pre>\n            <p>Always check <span class=\"doc-inline\">status</span> first. Maintenance mode also returns\n            <span class=\"doc-inline\">status:true</span> but has <strong>no</strong> <span class=\"doc-inline\">data</span> object — only a\n            <span class=\"doc-inline\">reason</span> message. Treat that as not authorised.</p>\n        </div>\n    </div>\n\n    <div class=\"card\">\n        <div class=\"doc-section\">\n            <h2>4. Response fields</h2>\n            <div class=\"table-scroll\">\n                <table class=\"responsive\">\n                    <thead><tr><th>Field</th><th>Meaning / how to use it</th></tr></thead>\n                    <tbody>\n                        <tr><td><span class=\"doc-inline\">status</span></td><td><span class=\"doc-inline\">true</span> = authorised. On <span class=\"doc-inline\">false</span>, read <span class=\"doc-inline\">reason</span>.</td></tr>\n                        <tr><td><span class=\"doc-inline\">reason</span></td><td>Only on failure or maintenance. See the error table below.</td></tr>\n                        <tr><td><span class=\"doc-inline\">data.real</span></td><td><span class=\"doc-inline\">game-user_key-serial-STATIC_WORDS</span>.</td></tr>\n                        <tr><td><span class=\"doc-inline\">data.token</span></td><td><span class=\"doc-inline\">md5(real)</span>. Recompute to detect a tampered reply.</td></tr>\n                        <tr><td><span class=\"doc-inline\">data.modname</span></td><td>Mod name for your menu / title. Set at <span class=\"doc-inline\">/Server → Change Mod Name</span>.</td></tr>\n                        <tr><td><span class=\"doc-inline\">data.mod_status</span></td><td><strong>Status text</strong>: <span class=\"doc-inline\">Safe</span> or <span class=\"doc-inline\">Anti-Cheat is High..!!</span>. Show as a badge.</td></tr>\n                        <tr><td><span class=\"doc-inline\">data.credit</span></td><td><strong>Floating text</strong>: free-form line drawn over the mod menu, e.g. <span class=\"doc-inline\">MOD STATUS :- 100% SAFE</span>.</td></tr>\n                        <tr><td><span class=\"doc-inline\">data.ESP … Setting</span></td><td>Eight <strong>mod feature</strong> gates. Values are the strings <span class=\"doc-inline\">\"on\"</span> / <span class=\"doc-inline\">\"off\"</span> — not booleans. Toggled at <span class=\"doc-inline\">/Server → Mod Features</span>.</td></tr>\n                        <tr><td><span class=\"doc-inline\">data.expired_date</span></td><td><strong>Expiry</strong> as ISO-8601 UTC. Compare with current UTC time before enabling features.</td></tr>\n                        <tr><td><span class=\"doc-inline\">data.EXP</span>, <span class=\"doc-inline\">data.exdate</span></td><td>Same expiry value, kept for legacy loaders.</td></tr>\n                        <tr><td><span class=\"doc-inline\">data.device</span></td><td>Maximum devices allowed for this key.</td></tr>\n                        <tr><td><span class=\"doc-inline\">data.rng</span></td><td>Unix timestamp (seconds) when the server built the reply — anti-replay heuristic.</td></tr>\n                    </tbody>\n                </table>\n            </div>\n        </div>\n\n        <div class=\"doc-section\">\n            <h2>5. Expiry &amp; devices</h2>\n            <p>A new key has no expiry. The <strong>first successful</strong> connect sets it to\n            <span class=\"doc-inline\">now + duration hours</span> (2, 5, 24, 72, 168, 336 or 720 hours,\n            chosen when the key is generated). After that it never moves and later calls return\n            <span class=\"doc-inline\">EXPIRED KEY</span>. The key's <span class=\"doc-inline\">device</span> limit counts\n            distinct serials; re-using the same serial is always allowed.</p>\n        </div>\n\n        <div class=\"doc-section\">\n            <h2>6. Status / error text</h2>\n            <p>All rejections are HTTP 200 with <span class=\"doc-inline\">status:false</span>:</p>\n            <div class=\"table-scroll\">\n                <table class=\"responsive\">\n                    <thead><tr><th>reason</th><th>Cause</th></tr></thead>\n                    <tbody>\n                        <tr><td><span class=\"doc-inline\">INVALID PARAMETER</span></td><td>A parameter is missing or empty</td></tr>\n                        <tr><td><span class=\"doc-inline\">Bad Parameter</span></td><td>Illegal characters or key longer than 36 chars</td></tr>\n                        <tr><td><span class=\"doc-inline\">USER OR GAME NOT REGISTERED</span></td><td>Key missing, or game does not match</td></tr>\n                        <tr><td><span class=\"doc-inline\">USER BLOCKED</span></td><td>Key is not active</td></tr>\n                        <tr><td><span class=\"doc-inline\">EXPIRED KEY</span></td><td>Expiry time is in the past</td></tr>\n                        <tr><td><span class=\"doc-inline\">MAX DEVICE REACHED</span></td><td>New serial and the device limit is full</td></tr>\n                        <tr><td>maintenance message</td><td><span class=\"doc-inline\">status:true</span>, no <span class=\"doc-inline\">data</span>. Show the message from <span class=\"doc-inline\">/Server → Offline Message</span>.</td></tr>\n                    </tbody>\n                </table>\n            </div>\n        </div>\n    </div>\n\n    <div class=\"card\">\n        <div class=\"doc-section\">\n            <h2>7. Use in C++</h2>\n            <p>Minimal libcurl POST — no JSON library needed to see the raw reply:</p>\n            <pre class=\"doc-code\"><code>// g++ connect.cpp -o connect -lcurl\n#include &lt;curl/curl.h&gt;\n#include &lt;iostream&gt;\n#include &lt;string&gt;\n\nstatic size_t onData(char* p, size_t size, size_t nmemb, void* out) {\n    static_cast&lt;std::string*&gt;(out)-&gt;append(p, size * nmemb);\n    return size * nmemb;\n}\n\nstd::string post(const std::string&amp; url, const std::string&amp; body) {\n    CURL* c = curl_easy_init();\n    std::string out;\n    curl_easy_setopt(c, CURLOPT_URL, url.c_str());\n    curl_easy_setopt(c, CURLOPT_POSTFIELDS, body.c_str());\n    curl_easy_setopt(c, CURLOPT_WRITEFUNCTION, onData);\n    curl_easy_setopt(c, CURLOPT_WRITEDATA, &amp;out);\n    curl_easy_setopt(c, CURLOPT_TIMEOUT, 15L);\n    CURLcode rc = curl_easy_perform(c);\n    if (rc != CURLE_OK) std::cerr &lt;&lt; curl_easy_strerror(rc) &lt;&lt; std::endl;\n    curl_easy_cleanup(c);\n    return out;\n}\n\nint main() {\n    std::string json = post(\"{{apiBase}}/connect\",\n        \"game=PUBG&amp;user_key=ANOY-2H-LYK0Y&amp;serial=DEVICE123\");\n    std::cout &lt;&lt; json &lt;&lt; std::endl;\n}</code></pre>\n            <p>Then parse it (example with <span class=\"doc-inline\">nlohmann/json</span>):</p>\n            <pre class=\"doc-code\"><code>#include &lt;nlohmann/json.hpp&gt;\n#include &lt;string&gt;\n\nvoid apply(const std::string&amp; json) {\n    auto r = nlohmann::json::parse(json, nullptr, false);\n    if (r.is_discarded()) return;               // bad JSON\n\n    if (!r.value(\"status\", false)) {\n        ShowMessage(r.value(\"reason\", \"UNKNOWN ERROR\"));  // EXPIRED KEY, USER BLOCKED ...\n        return;\n    }\n    if (!r.contains(\"data\")) {                  // maintenance mode\n        ShowMessage(r.value(\"reason\", \"Server is Under Maintenance\"));\n        return;\n    }\n\n    const auto&amp; d = r[\"data\"];\n    std::string modName  = d.value(\"modname\", \"\");       // \"VIP MOD\"\n    std::string status   = d.value(\"mod_status\", \"\");    // \"Safe\" / \"Anti-Cheat is High..!!\"\n    std::string floating = d.value(\"credit\", \"\");        // floating text\n    std::string expiry   = d.value(\"expired_date\", \"\");  // ISO-8601 UTC\n    int maxDevices       = d.value(\"device\", 1);\n    std::string token    = d.value(\"token\", \"\");\n\n    bool esp       = d.value(\"ESP\", \"off\") == \"on\";\n    bool aim       = d.value(\"AIM\", \"off\") == \"on\";\n    bool silentAim = d.value(\"SilentAim\", \"off\") == \"on\";\n    bool bullet    = d.value(\"BulletTrack\", \"off\") == \"on\";\n    bool item      = d.value(\"Item\", \"off\") == \"on\";\n    bool floatingW = d.value(\"Floating\", \"off\") == \"on\";\n    bool memory    = d.value(\"Memory\", \"off\") == \"on\";\n    bool setting   = d.value(\"Setting\", \"off\") == \"on\";\n\n    SetMenuTitle(modName);\n    DrawFloatingText(floating);\n    DrawStatusBadge(status);\n    EnableFeatures(esp, aim, silentAim, bullet, item, floatingW, memory, setting);\n    // verify token == md5(game + \"-\" + key + \"-\" + serial + \"-\" + STATIC_WORDS)\n    // and compare expiry with current UTC time before starting the mod.\n}</code></pre>\n            <p class=\"doc-note\">The <span class=\"doc-inline\">ShowMessage</span>, <span class=\"doc-inline\">DrawFloatingText</span>\n            and <span class=\"doc-inline\">EnableFeatures</span> calls are placeholders for your own UI/hooks —\n            the API itself is just JSON over HTTPS.</p>\n        </div>\n\n        <div class=\"doc-section\">\n            <h2>8. Other endpoints</h2>\n            <div class=\"table-scroll\">\n                <table class=\"responsive\">\n                    <thead><tr><th>Method / path</th><th>Returns</th></tr></thead>\n                    <tbody>\n                        <tr><td><span class=\"doc-inline\">GET /api/health</span></td><td><span class=\"doc-inline\">ok</span>, DB + lib channel, <span class=\"doc-inline\">13/13</span> schema check</td></tr>\n                        <tr><td><span class=\"doc-inline\">GET /api/lib/version</span></td><td>plain text version, e.g. <span class=\"doc-inline\">1.0</span> — first line read by the loader</td></tr>\n                        <tr><td><span class=\"doc-inline\">GET /api/lib/download</span></td><td>current loader ZIP (or 302 to an external URL)</td></tr>\n                        <tr><td><span class=\"doc-inline\">GET /api/lib/manifest</span></td><td>JSON <span class=\"doc-inline\">{ ok, version, available, size, sha256, source }</span> — read by the loader's mandatory update check before sign-in</td></tr>\n                        <tr><td><span class=\"doc-inline\">GET /api/lib/info</span></td><td>JSON list of uploaded releases</td></tr>\n                        <tr><td><span class=\"doc-inline\">GET /connect</span> (no params)</td><td><span class=\"doc-inline\">web_info</span> / <span class=\"doc-inline\">web__dev</span> panel info</td></tr>\n                        <tr><td><span class=\"doc-inline\">GET /api/v1/keys</span> …</td><td>Key-management REST API — needs a personal API key, documented at <a href=\"/api-docs\">/api-docs</a></td></tr>\n                    </tbody>\n                </table>\n            </div>\n        </div>\n\n        <div class=\"doc-section\">\n            <h2>9. Where to change the values</h2>\n            <div class=\"table-scroll\">\n                <table class=\"responsive\">\n                    <thead><tr><th>Value</th><th>Panel location</th></tr></thead>\n                    <tbody>\n                        <tr><td><span class=\"doc-inline\">modname</span></td><td><span class=\"doc-inline\">/Server → Change Mod Name</span></td></tr>\n                        <tr><td><span class=\"doc-inline\">mod_status</span>, <span class=\"doc-inline\">credit</span></td><td><span class=\"doc-inline\">/Server → Floating Text</span></td></tr>\n                        <tr><td><span class=\"doc-inline\">ESP … Setting</span></td><td><span class=\"doc-inline\">/Server → Mod Features</span> (Owner)</td></tr>\n                        <tr><td>Maintenance message</td><td><span class=\"doc-inline\">/Server → Server Maintenance</span></td></tr>\n                        <tr><td>Duration, device limit, key status</td><td><span class=\"doc-inline\">/keys</span>, <span class=\"doc-inline\">/keys/generate</span>, <span class=\"doc-inline\">/keys/edit</span></td></tr>\n                        <tr><td>Loader version / ZIP</td><td><span class=\"doc-inline\">/lib</span></td></tr>\n                    </tbody>\n                </table>\n            </div>\n        </div>\n    </div>\n</div>\n","keys_edit":"<div class=\"page-head\">\n    <div class=\"page-head-main\">\n        <a href=\"/keys\" class=\"icon-btn lg\" aria-label=\"Back to keys\">{{icon \"chevron-left\"}}</a>\n        <div>\n            <h1 class=\"page-title\">Edit key</h1>\n            <p class=\"page-sub mono\">{{key.user_key}}</p>\n        </div>\n    </div>\n    <div class=\"page-actions\">\n        <button type=\"button\" class=\"btn btn-secondary\" data-copy-text=\"{{key.user_key}}\">{{icon \"copy\"}}Copy key</button>\n    </div>\n</div>\n\n{{> msgStatus}}\n\n<div class=\"grid-main\">\n<section class=\"card\">\n    <div class=\"card-head\">\n        <div class=\"tile\">{{icon \"pencil\"}}</div>\n        <div><h2 class=\"card-title\">Settings</h2><div class=\"card-sub\">{{#if user.isOwner}}Every field of this key{{else}}Status of this key{{/if}}</div></div>\n    </div>\n<form method=\"post\" action=\"/keys/edit\" class=\"form\" novalidate data-busy-form>\n    <input type=\"hidden\" name=\"id_keys\" value=\"{{key.id_keys}}\">\n    {{#if user.isOwner}}\n    <div class=\"field {{#if errors.user_key}}invalid{{/if}}\">\n        <label class=\"label\" for=\"user_key\">Key</label>\n        <div class=\"input-wrap\">{{icon \"key-round\" \"lead\"}}\n        <input type=\"text\" class=\"input mono upper\" name=\"user_key\" id=\"user_key\" value=\"{{form.user_key}}\" required maxlength=\"64\" autocomplete=\"off\" autocapitalize=\"characters\" spellcheck=\"false\"></div>\n        {{#if errors.user_key}}<div class=\"error\">{{icon \"circle-alert\"}}<span>{{errors.user_key}}</span></div>{{/if}}\n    </div>\n    <div class=\"field-row\">\n        <div class=\"field {{#if errors.game}}invalid{{/if}}\">\n            <label class=\"label\" for=\"game\">Game</label>\n            {{{selects.game}}}\n            {{#if errors.game}}<div class=\"error\">{{icon \"circle-alert\"}}<span>{{errors.game}}</span></div>{{/if}}\n        </div>\n        <div class=\"field {{#if errors.status}}invalid{{/if}}\">\n            <label class=\"label\" for=\"status\">Status</label>\n            {{{selects.status}}}\n            {{#if errors.status}}<div class=\"error\">{{icon \"circle-alert\"}}<span>{{errors.status}}</span></div>{{/if}}\n        </div>\n    </div>\n    <div class=\"field-row\">\n        <div class=\"field {{#if errors.duration}}invalid{{/if}}\">\n            <label class=\"label\" for=\"duration\">Duration (hours)</label>\n            <div class=\"input-wrap\">{{icon \"clock\" \"lead\"}}\n            <input type=\"number\" class=\"input\" name=\"duration\" id=\"duration\" value=\"{{form.duration}}\" min=\"1\" max=\"100000\" required inputmode=\"numeric\"></div>\n            {{#if errors.duration}}<div class=\"error\">{{icon \"circle-alert\"}}<span>{{errors.duration}}</span></div>{{/if}}\n        </div>\n        <div class=\"field {{#if errors.max_devices}}invalid{{/if}}\">\n            <label class=\"label\" for=\"max_devices\">Devices allowed</label>\n            <div class=\"input-wrap\">{{icon \"smartphone\" \"lead\"}}\n            <input type=\"number\" class=\"input\" name=\"max_devices\" id=\"max_devices\" value=\"{{form.max_devices}}\" min=\"1\" max=\"100\" required inputmode=\"numeric\"></div>\n            {{#if errors.max_devices}}<div class=\"error\">{{icon \"circle-alert\"}}<span>{{errors.max_devices}}</span></div>{{/if}}\n        </div>\n    </div>\n    <div class=\"field-row\">\n        <div class=\"field {{#if errors.expired_date}}invalid{{/if}}\">\n            <label class=\"label\" for=\"expired_date\">Expires (IST)</label>\n            <div class=\"input-wrap\">{{icon \"calendar\" \"lead\"}}\n            <input type=\"text\" class=\"input mono\" name=\"expired_date\" id=\"expired_date\" value=\"{{form.expired_date}}\" placeholder=\"Not started yet\" autocomplete=\"off\"></div>\n            {{#if errors.expired_date}}<div class=\"error\">{{icon \"circle-alert\"}}<span>{{errors.expired_date}}</span></div>{{else}}<div class=\"hint\">YYYY-MM-DD HH:MM:SS, Indian time (IST). Empty = not used yet.</div>{{/if}}\n        </div>\n        <div class=\"field {{#if errors.registrator}}invalid{{/if}}\">\n            <label class=\"label\" for=\"registrator\">Created by</label>\n            <div class=\"input-wrap\">{{icon \"user\" \"lead\"}}\n            <input type=\"text\" class=\"input\" name=\"registrator\" id=\"registrator\" value=\"{{form.registrator}}\" maxlength=\"32\" autocomplete=\"off\"></div>\n            {{#if errors.registrator}}<div class=\"error\">{{icon \"circle-alert\"}}<span>{{errors.registrator}}</span></div>{{/if}}\n        </div>\n    </div>\n    <div class=\"field {{#if errors.devices}}invalid{{/if}}\">\n        <label class=\"label\" for=\"devices\">Registered devices</label>\n        <textarea class=\"input mono\" name=\"devices\" id=\"devices\" rows=\"{{key.deviceRows}}\" spellcheck=\"false\" placeholder=\"No devices yet\">{{form.devices}}</textarea>\n        {{#if errors.devices}}<div class=\"error\">{{icon \"circle-alert\"}}<span>{{errors.devices}}</span></div>{{else}}<div class=\"hint\">One device ID per line.</div>{{/if}}\n    </div>\n    {{else}}\n    <div class=\"field {{#if errors.status}}invalid{{/if}}\">\n        <label class=\"label\" for=\"status\">Status</label>\n        {{{selects.status}}}\n        {{#if errors.status}}<div class=\"error\">{{icon \"circle-alert\"}}<span>{{errors.status}}</span></div>{{/if}}\n    </div>\n    {{/if}}\n    <button type=\"submit\" class=\"btn btn-primary btn-block\" data-busy-label=\"Saving…\">{{icon \"check\"}}Save changes</button>\n</form>\n</section>\n\n<aside class=\"stack\">\n    <section class=\"card\">\n        <div class=\"card-head\">\n            <div class=\"tile teal\">{{icon \"info\"}}</div>\n            <div><h2 class=\"card-title\">Details</h2><div class=\"card-sub\">Live state of this key</div></div>\n        </div>\n        <div class=\"list\">\n            <div class=\"list-row\"><span class=\"lr-label\">{{icon \"gamepad-2\" \"i-sm\"}}Game</span><span class=\"lr-value\">{{key.game}}</span></div>\n            <div class=\"list-row\"><span class=\"lr-label\">{{icon \"clock\" \"i-sm\"}}Duration</span><span class=\"lr-value\">{{key.durationLabel}}</span></div>\n            <div class=\"list-row\"><span class=\"lr-label\">{{icon \"smartphone\" \"i-sm\"}}Devices</span><span class=\"lr-value num\">{{key.deviceTotal}} of {{key.max_devices}}</span></div>\n            <div class=\"list-row\"><span class=\"lr-label\">{{icon \"calendar\" \"i-sm\"}}Expires</span><span class=\"lr-value\">{{#if key.expiresLabel}}{{key.expiresLabel}}{{else}}Not started yet{{/if}}</span></div>\n            <div class=\"list-row\"><span class=\"lr-label\">{{icon \"user\" \"i-sm\"}}Created by</span><span class=\"lr-value\">{{key.registrator}}</span></div>\n        </div>\n    </section>\n    <section class=\"card\">\n        <div class=\"card-head\">\n            <div class=\"tile orange\">{{icon \"wrench\"}}</div>\n            <div><h2 class=\"card-title\">Actions</h2><div class=\"card-sub\">Applied immediately</div></div>\n        </div>\n        <div class=\"actions\">\n            <button type=\"button\" class=\"btn btn-secondary\" data-key-action=\"reset\" data-key=\"{{key.user_key}}\">{{icon \"rotate-ccw\"}}Reset devices</button>\n            <button type=\"button\" class=\"btn btn-danger\" data-key-action=\"delete\" data-key=\"{{key.user_key}}\" data-after=\"/keys\">{{icon \"trash-2\"}}Delete key</button>\n        </div>\n    </section>\n</aside>\n</div>\n","keys_generate":"<div class=\"page-head\">\n    <div>\n        <h1 class=\"page-title\">Generate keys</h1>\n        <p class=\"page-sub\">Balance: {{#if unlimited}}Unlimited{{else}}₹{{user.saldoLabel}}{{/if}}</p>\n    </div>\n    <div class=\"page-actions\">\n        <a href=\"/keys\" class=\"btn btn-secondary\">{{icon \"key-round\"}}All keys</a>\n    </div>\n</div>\n\n{{> msgStatus}}\n\n{{#if flash.user_key}}\n<section class=\"card highlight keys-out\" id=\"generated\" style=\"margin-bottom:20px\">\n    <div class=\"card-head\">\n        <div class=\"tile green\">{{icon \"circle-check\"}}</div>\n        <div><h2 class=\"card-title\">New keys ready</h2><div class=\"card-sub\">{{flash.game}} · {{flash.max_devices}} device(s) · the duration starts when the key is first used.</div>{{#if flash.created_label}}<div class=\"card-sub\">Created {{flash.created_label}} · if first used now, expires {{flash.expires_if_now}}</div>{{/if}}</div>\n        <span class=\"spacer\"></span>\n        <button type=\"button\" class=\"btn btn-primary btn-sm\" data-copy-target=\"generated-keys\">{{icon \"copy\"}}Copy all</button>\n    </div>\n    <textarea class=\"input\" id=\"generated-keys\" readonly rows=\"4\" aria-label=\"Generated keys\">{{flash.user_key}}</textarea>\n</section>\n{{/if}}\n\n{{#if balanceLow}}\n<div class=\"alert alert-warning\">{{icon \"triangle-alert\"}}<p>Your balance is empty. Ask your admin to add balance before creating keys.</p></div>\n{{/if}}\n\n<form method=\"post\" action=\"/keys/generate\" class=\"grid-main\" id=\"generate-form\" novalidate data-busy-form\n      data-prices=\"{{priceJson}}\" data-prefixes=\"{{prefixJson}}\" data-unlimited=\"{{#if unlimited}}1{{/if}}\"\n      data-saldo=\"{{user.saldo}}\" data-min=\"{{customMin}}\" data-max=\"{{customMax}}\">\n    <input type=\"hidden\" name=\"request_id\" id=\"request_id\" value=\"\">\n    <input type=\"hidden\" name=\"game\" value=\"PUBG\">\n\n    <section class=\"card\">\n        <div class=\"card-head\">\n            <div class=\"tile\">{{icon \"wand-sparkles\"}}</div>\n            <div><h2 class=\"card-title\">Key options</h2><div class=\"card-sub\">Pick a duration, devices and key type.</div></div>\n        </div>\n        <div class=\"form\">\n            <div class=\"field {{#if errors.duration}}invalid{{/if}}\">\n                <span class=\"label\">{{icon \"clock\" \"i-sm\"}}Duration</span>\n                <div class=\"choice-grid\" role=\"radiogroup\" aria-label=\"Duration\">\n                    {{#each durations}}\n                    <label class=\"choice\"><input type=\"radio\" name=\"duration\" value=\"{{this.hours}}\" {{#if (eq @root.form.duration this.hours)}}checked{{/if}}><span><b>{{this.label}}</b><small>{{this.price}}</small></span></label>\n                    {{/each}}\n                </div>\n                {{#if errors.duration}}<div class=\"error\">{{icon \"circle-alert\"}}<span>{{errors.duration}}</span></div>{{else}}<div class=\"hint\">Price per device.</div>{{/if}}\n            </div>\n\n            <div class=\"field-row\">\n                <div class=\"field {{#if errors.max_devices}}invalid{{/if}}\">\n                    <label class=\"label\" for=\"max_devices\">{{icon \"smartphone\" \"i-sm\"}}Devices per key</label>\n                    <div class=\"stepper\">\n                        <button type=\"button\" data-step=\"-1\" data-target=\"max_devices\" aria-label=\"Fewer devices\">{{icon \"minus\" \"i-sm\"}}</button>\n                        <input type=\"number\" class=\"input\" name=\"max_devices\" id=\"max_devices\" min=\"1\" max=\"100\" step=\"1\" inputmode=\"numeric\" required value=\"{{#if form.max_devices}}{{form.max_devices}}{{else}}1{{/if}}\">\n                        <button type=\"button\" data-step=\"1\" data-target=\"max_devices\" aria-label=\"More devices\">{{icon \"plus\" \"i-sm\"}}</button>\n                    </div>\n                    {{#if errors.max_devices}}<div class=\"error\">{{icon \"circle-alert\"}}<span>{{errors.max_devices}}</span></div>{{/if}}\n                </div>\n                <div class=\"field\">\n                    <span class=\"label\">{{icon \"layers\" \"i-sm\"}}Key type</span>\n                    <div class=\"segmented block\" role=\"radiogroup\" aria-label=\"Key type\">\n                        <label><input type=\"radio\" name=\"custom\" value=\"\" {{#unless form.custom}}checked{{/unless}}><span>{{icon \"sparkles\" \"i-sm\"}}Random</span></label>\n                        <label><input type=\"radio\" name=\"custom\" value=\"1\" {{#if form.custom}}checked{{/if}}><span>{{icon \"pencil\" \"i-sm\"}}Custom</span></label>\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"field {{#if errors.count}}invalid{{/if}}\" id=\"count-field\">\n                <label class=\"label\" for=\"count\">{{icon \"hash\" \"i-sm\"}}Number of keys</label>\n                <div class=\"stepper\" style=\"max-width:260px\">\n                    <button type=\"button\" data-step=\"-1\" data-target=\"count\" aria-label=\"Fewer keys\">{{icon \"minus\" \"i-sm\"}}</button>\n                    <input type=\"number\" class=\"input\" name=\"count\" id=\"count\" min=\"1\" max=\"100\" step=\"1\" inputmode=\"numeric\" value=\"{{#if form.count}}{{form.count}}{{else}}1{{/if}}\">\n                    <button type=\"button\" data-step=\"1\" data-target=\"count\" aria-label=\"More keys\">{{icon \"plus\" \"i-sm\"}}</button>\n                </div>\n                {{#if errors.count}}<div class=\"error\">{{icon \"circle-alert\"}}<span>{{errors.count}}</span></div>{{else}}<div class=\"hint\">Up to 100 keys at once.</div>{{/if}}\n            </div>\n\n            <div class=\"field {{#if errors.custom_key}}invalid{{/if}}\" id=\"custom-field\" hidden>\n                <label class=\"label\" for=\"custom_key\">{{icon \"pencil\" \"i-sm\"}}Custom ending</label>\n                <div class=\"affix\">\n                    {{icon \"key-round\" \"lead\"}}\n                    <span class=\"affix-text\" id=\"custom-prefix\">PREFIX-</span>\n                    <input type=\"text\" class=\"input mono upper\" name=\"custom_key\" id=\"custom_key\" value=\"{{form.custom_key}}\"\n                           maxlength=\"64\" autocomplete=\"off\" autocapitalize=\"characters\" spellcheck=\"false\" placeholder=\"VIP01\">\n                </div>\n                {{#if errors.custom_key}}<div class=\"error\">{{icon \"circle-alert\"}}<span>{{errors.custom_key}}</span></div>{{else}}<div class=\"hint\">{{customMin}}–{{customMax}} letters or numbers. Creates exactly one key.</div>{{/if}}\n            </div>\n        </div>\n    </section>\n\n    <aside class=\"card sticky-side\">\n        <div class=\"card-head\">\n            <div class=\"tile teal\">{{icon \"key-round\"}}</div>\n            <div><h2 class=\"card-title\">Summary</h2><div class=\"card-sub\">What will be created</div></div>\n        </div>\n        <div class=\"label\" style=\"margin-bottom:6px\">Example key</div>\n        <div class=\"key-preview\" id=\"key-example\">—</div>\n        <div class=\"summary list\" style=\"margin-top:14px\">\n            <div class=\"list-row\"><span>Price per key</span><span class=\"num\" id=\"unit-price\">—</span></div>\n            <div class=\"list-row\"><span>Total</span><span class=\"total\" id=\"total-price\">—</span></div>\n        </div>\n        <div class=\"error\" id=\"balance-error\" hidden>{{icon \"circle-alert\"}}<span>This order is more than your balance.</span></div>\n        <button type=\"submit\" class=\"btn btn-primary btn-block btn-lg\" id=\"generate-submit\" data-busy-label=\"Creating…\" style=\"margin-top:16px\">{{icon \"wand-sparkles\"}}Generate</button>\n    </aside>\n</form>\n","keys_list":"<div class=\"page-head\">\n    <div>\n        <h1 class=\"page-title\">Keys</h1>\n        <p class=\"page-sub\">{{keyTotal}} {{#if user.isOwner}}keys in total{{else}}keys created by you{{/if}}</p>\n    </div>\n    <div class=\"page-actions\">\n        <a href=\"/keys/download\" class=\"btn btn-secondary\">{{icon \"download\"}}Export</a>\n        <a href=\"/keys/generate\" class=\"btn btn-primary\">{{icon \"plus\"}}Generate keys</a>\n    </div>\n</div>\n\n{{> msgStatus}}\n\n<section class=\"card card-flush\">\n    <div class=\"toolbar\">\n        <div class=\"input-wrap\">\n            {{icon \"search\" \"lead\"}}\n            <input type=\"search\" class=\"input\" id=\"keys-search\" placeholder=\"Search keys\" aria-label=\"Search keys\" autocomplete=\"off\" spellcheck=\"false\">\n        </div>\n        <select class=\"input\" id=\"keys-status\" aria-label=\"Filter by status\">\n            <option value=\"\">All keys</option>\n            <option value=\"unused\">Unused</option>\n            <option value=\"used\">In use</option>\n            <option value=\"expired\">Expired</option>\n            <option value=\"blocked\">Blocked</option>\n        </select>\n        <span class=\"spacer\"></span>\n        <form method=\"post\" action=\"/keys/deleteexp\" data-confirm=\"Delete all expired keys?\" data-confirm-detail=\"Expired keys stop working anyway. This cannot be undone.\">\n            <button type=\"submit\" class=\"btn btn-secondary btn-sm\">{{icon \"hourglass\"}}Delete expired</button>\n        </form>\n        <form method=\"post\" action=\"/keys/deleteunused\" data-confirm=\"Delete all unused keys?\" data-confirm-detail=\"Never-used keys are refunded to their creator. This cannot be undone.\">\n            <button type=\"submit\" class=\"btn btn-danger btn-sm\">{{icon \"trash-2\"}}Delete unused</button>\n        </form>\n    </div>\n\n    <div class=\"table-wrap\">\n        <table class=\"responsive\" id=\"keys-table\" aria-live=\"polite\">\n            <thead>\n                <tr><th>Key</th><th>Duration</th><th>Devices</th><th>Status</th><th>Expires</th>{{#if user.isOwner}}<th>Created by</th>{{/if}}<th class=\"actions-cell\"><span class=\"sr-only\">Actions</span></th></tr>\n            </thead>\n            <tbody id=\"keys-body\">\n                <tr class=\"skeleton\"><td colspan=\"7\"><span class=\"sk\" style=\"width:62%\"></span></td></tr>\n                <tr class=\"skeleton\"><td colspan=\"7\"><span class=\"sk\" style=\"width:48%\"></span></td></tr>\n                <tr class=\"skeleton\"><td colspan=\"7\"><span class=\"sk\" style=\"width:56%\"></span></td></tr>\n            </tbody>\n        </table>\n    </div>\n    <div class=\"pager\">\n        <span id=\"keys-range\" class=\"num\">&nbsp;</span>\n        <div class=\"row\" style=\"gap:4px\">\n            <button type=\"button\" class=\"icon-btn\" id=\"keys-prev\" aria-label=\"Previous page\" disabled>{{icon \"chevron-left\"}}</button>\n            <button type=\"button\" class=\"icon-btn\" id=\"keys-next\" aria-label=\"Next page\" disabled>{{icon \"chevron-right\"}}</button>\n        </div>\n    </div>\n</section>\n\n<script>window.ANOY_KEYS = { owner: {{#if user.isOwner}}true{{else}}false{{/if}} };</script>\n","layout":"<!doctype html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"utf-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n    <meta name=\"theme-color\" content=\"#000000\">\n    <meta name=\"color-scheme\" content=\"dark\">\n    <meta name=\"description\" content=\"{{brand}} licence panel\">\n    <meta name=\"robots\" content=\"noindex\">\n    <link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\">\n    <link rel=\"preload\" href=\"/assets/fonts/inter-latin-wght-normal.woff2\" as=\"font\" type=\"font/woff2\" crossorigin>\n    <title>{{title}} · {{brand}}</title>\n    <link rel=\"stylesheet\" href=\"/assets/css/ui.css\">\n</head>\n<body data-icons=\"{{iconSprite}}\">\n    <div class=\"shell\">\n        {{> header}}\n        <div class=\"scrim\" data-nav-close></div>\n        <div class=\"main\">\n            <header class=\"topbar\">\n                <button type=\"button\" class=\"icon-btn lg\" data-nav-open aria-label=\"Open menu\">{{icon \"menu\"}}</button>\n                <a href=\"/dashboard\" class=\"brand\">{{brand}}</a>\n                <a href=\"/settings\" class=\"icon-btn lg\" aria-label=\"Account settings\">{{icon \"user-round\"}}</a>\n            </header>\n            <main class=\"content fade-in\" id=\"main-content\">\n                {{{content}}}\n            </main>\n            <footer class=\"footer\">\n                <span>&copy; {{year}} {{brand}}</span>\n                <span>Panel v{{appVersion}}</span>\n            </footer>\n        </div>\n        <nav class=\"tabbar\" aria-label=\"Quick navigation\">\n            <a href=\"/dashboard\" class=\"{{#if navDashboard}}active{{/if}}\">{{icon \"layout-dashboard\"}}<span>Home</span></a>\n            <a href=\"/keys\" class=\"{{#if navKeys}}active{{/if}}\">{{icon \"key-round\"}}<span>Keys</span></a>\n            <a href=\"/keys/generate\" class=\"tab-cta\" aria-label=\"Generate keys\"><span class=\"fab\">{{icon \"plus\"}}</span></a>\n            <a href=\"/settings\" class=\"{{#if navSettings}}active{{/if}}\">{{icon \"settings\"}}<span>Settings</span></a>\n            <button type=\"button\" data-nav-open>{{icon \"menu\"}}<span>More</span></button>\n        </nav>\n    </div>\n    <script src=\"/assets/js/app-ui.js\"></script>\n</body>\n</html>\n","lib":"<div class=\"page-head\">\n    <div>\n        <h1 class=\"page-title\">Library</h1>\n        <p class=\"page-sub\">Publishing a new version makes every loader update before sign-in.</p>\n    </div>\n    <div class=\"page-actions\">\n        <a href=\"/api/lib/download\" class=\"btn btn-secondary\">{{icon \"download\"}}Download current</a>\n    </div>\n</div>\n\n{{> msgStatus}}\n\n<section class=\"card\" style=\"margin-bottom:20px\">\n    <div class=\"hero\">\n        <div class=\"tile tile-lg purple\">{{icon \"package\"}}</div>\n        <div style=\"flex:1;min-width:180px\">\n            <div class=\"hero-label\">Current version</div>\n            <div class=\"hero-value mono\">{{currentVersion}}</div>\n        </div>\n        <div class=\"list\" style=\"min-width:240px;flex:0 1 380px\">\n            <div class=\"list-row\"><span class=\"lr-label\">{{icon \"file-archive\" \"i-sm\"}}File</span><span class=\"lr-value mono\">{{#if release.file_name}}{{release.file_name}}{{else}}—{{/if}}</span></div>\n            <div class=\"list-row\"><span class=\"lr-label\">{{icon \"cloud-upload\" \"i-sm\"}}Source</span><span class=\"lr-value\">{{#if release.external_url}}External link{{else}}{{#if release.sha256}}Stored file{{else}}<span class=\"status warn\">Nothing published yet</span>{{/if}}{{/if}}</span></div>\n            <div class=\"list-row\"><span class=\"lr-label\">{{icon \"user\" \"i-sm\"}}Published by</span><span class=\"lr-value\">{{#if release.uploaded_by}}{{release.uploaded_by}}{{else}}—{{/if}}</span></div>\n        </div>\n    </div>\n</section>\n\n<section class=\"card publish-card\" id=\"publish-card\">\n    <div class=\"card-head\">\n        <div class=\"tile\">{{icon \"upload\"}}</div>\n        <div><h2 class=\"card-title\">Publish a release</h2><div class=\"card-sub\">Upload a .so library or a .zip containing it (up to {{maxUploadMb}} MB), or give an https:// link.</div></div>\n    </div>\n    <form id=\"lib-form\" class=\"form\" novalidate>\n        <div class=\"field\">\n            <label class=\"label\" for=\"lib-version\">Version</label>\n            <div class=\"input-wrap has-trail\">\n                {{icon \"tag\" \"lead\"}}\n                <input type=\"text\" class=\"input mono\" name=\"version\" id=\"lib-version\" value=\"{{suggestedVersion}}\" maxlength=\"32\" autocomplete=\"off\" spellcheck=\"false\">\n                <div class=\"trail\"><button type=\"button\" class=\"icon-btn accent\" id=\"lib-bump\" aria-label=\"Bump version\" title=\"Bump version\">{{icon \"plus\"}}</button></div>\n            </div>\n            <div class=\"hint\">Current: <span class=\"mono\">{{currentVersion}}</span></div>\n        </div>\n        <div class=\"field\">\n            <span class=\"label\">File</span>\n            <label class=\"dropzone\" id=\"lib-drop\">\n                <input type=\"file\" name=\"myfile\" id=\"lib-file\" accept=\".so,.zip,application/zip,application/octet-stream\" aria-label=\"Library file\">\n                <span class=\"tile\">{{icon \"upload\"}}</span>\n                <b>Choose a file or drop it here</b>\n                <span class=\"file-name\" id=\"lib-file-name\">.so or .zip</span>\n            </label>\n            <button type=\"button\" class=\"btn btn-plain btn-sm\" id=\"lib-file-clear\" hidden>{{icon \"x\"}}Remove file</button>\n        </div>\n        <div class=\"or-divider\" aria-hidden=\"true\"><span>or</span></div>\n        <div class=\"field\">\n            <label class=\"label\" for=\"lib-url\">External link</label>\n            <div class=\"input-wrap\">{{icon \"link\" \"lead\"}}\n            <input type=\"url\" class=\"input\" name=\"external_url\" id=\"lib-url\" placeholder=\"https://…\" autocomplete=\"off\" spellcheck=\"false\" inputmode=\"url\"></div>\n            <div class=\"hint\" id=\"lib-url-hint\">Must start with https://. If you also choose a file, the file is published and this link is ignored.</div>\n        </div>\n        <div class=\"field\">\n            <label class=\"label\" for=\"lib-notes\">Notes (optional)</label>\n            <div class=\"input-wrap\">{{icon \"pencil\" \"lead\"}}\n            <input type=\"text\" class=\"input\" name=\"notes\" id=\"lib-notes\" maxlength=\"500\" autocomplete=\"off\"></div>\n        </div>\n        <button type=\"submit\" class=\"btn btn-primary btn-block\" id=\"lib-submit\">{{icon \"upload\"}}Publish</button>\n        <div class=\"progress\" id=\"lib-progress\" hidden>\n            <div class=\"progress-track\" role=\"progressbar\" aria-label=\"Upload progress\" aria-valuemin=\"0\" aria-valuemax=\"100\" aria-valuenow=\"0\"><div class=\"progress-fill\" id=\"lib-progress-fill\"></div></div>\n            <div class=\"progress-meta\"><span id=\"lib-progress-message\" aria-live=\"polite\">Preparing…</span><span id=\"lib-progress-percent\">0%</span></div>\n        </div>\n        <div id=\"lib-result\" aria-live=\"polite\"></div>\n    </form>\n</section>\n\n<script>\n(function () {\n    'use strict';\n    var MAX = Number('{{maxUploadMb}}') * 1024 * 1024;\n    var byId = function (id) { return document.getElementById(id); };\n\n    function say(box, text, ok) {\n        box.textContent = '';\n        var p = document.createElement('p');\n        p.className = ok ? 'hint' : 'error';\n        p.style.marginTop = '12px';\n        p.textContent = text;\n        box.appendChild(p);\n    }\n    function bytes(n) {\n        n = Number(n) || 0;\n        if (n < 1024) return n + ' B';\n        if (n < 1048576) return (n / 1024).toFixed(1) + ' KB';\n        return (n / 1048576).toFixed(2) + ' MB';\n    }\n    function progress(pct, message, state) {\n        var box = byId('lib-progress');\n        box.hidden = false;\n        box.className = 'progress' + (state ? ' ' + state : '');\n        var v = Math.max(0, Math.min(100, Math.round(pct)));\n        byId('lib-progress-fill').style.width = v + '%';\n        box.querySelector('[role=progressbar]').setAttribute('aria-valuenow', String(v));\n        byId('lib-progress-percent').textContent = v + '%';\n        byId('lib-progress-message').textContent = message;\n    }\n    function busy(btn, on, label) {\n        if (on) { btn.dataset.html = btn.innerHTML; btn.textContent = label; btn.disabled = true; }\n        else { if (btn.dataset.html) btn.innerHTML = btn.dataset.html; btn.disabled = false; }\n    }\n    function validVersion(v) { return /^[A-Za-z0-9][A-Za-z0-9._+-]{0,31}$/.test(v); }\n    function validUrl(u) {\n        if (!/^https:\\/\\/\\S+$/i.test(u)) return false;\n        try { return new URL(u).protocol === 'https:'; } catch (e) { return false; }\n    }\n\n    function readBase64(file, onProgress) {\n        return new Promise(function (resolve, reject) {\n            var reader = new FileReader();\n            reader.onprogress = function (e) { if (e.lengthComputable) onProgress(e.loaded / e.total); };\n            reader.onload = function () {\n                var s = String(reader.result || ''); var i = s.indexOf(',');\n                resolve(i >= 0 ? s.slice(i + 1) : '');\n            };\n            reader.onerror = function () { reject(new Error('Could not read the selected file.')); };\n            reader.readAsDataURL(file);\n        });\n    }\n    function send(payload, onProgress) {\n        return new Promise(function (resolve, reject) {\n            var xhr = new XMLHttpRequest();\n            xhr.open('POST', '/lib', true);\n            xhr.setRequestHeader('Content-Type', 'application/json');\n            xhr.timeout = 120000;\n            if (xhr.upload) xhr.upload.onprogress = function (e) { if (e.lengthComputable) onProgress(e.loaded, e.total); };\n            xhr.onload = function () {\n                var data = null;\n                try { data = JSON.parse(xhr.responseText); } catch (e) { /* not JSON */ }\n                if (xhr.status >= 200 && xhr.status < 300 && data && data.ok) resolve(data);\n                else if (xhr.status === 413) reject(new Error('The file is too large for the server. Use an external link.'));\n                else reject(new Error((data && data.error) || ('The server answered ' + xhr.status + '. Nothing was changed.')));\n            };\n            xhr.onerror = function () { reject(new Error('Network error. Check your connection; nothing was changed.')); };\n            xhr.ontimeout = function () { reject(new Error('The upload timed out. Nothing was changed.')); };\n            xhr.send(JSON.stringify(payload));\n        });\n    }\n\n    var drop = byId('lib-drop'), fileInput = byId('lib-file');\n    var urlHint = byId('lib-url-hint'), clearFile = byId('lib-file-clear');\n    var URL_HINT = urlHint.textContent;\n    function syncFile() {\n        var f = fileInput.files[0];\n        byId('lib-file-name').textContent = f ? f.name + ' · ' + bytes(f.size) : '.so or .zip';\n        clearFile.hidden = !f;\n        drop.classList.toggle('has-file', !!f);\n        // File wins: say so next to the link while a file is selected.\n        urlHint.textContent = f && byId('lib-url').value.trim()\n            ? 'A file is selected, so this link will be ignored.' : URL_HINT;\n    }\n    fileInput.addEventListener('change', syncFile);\n    byId('lib-url').addEventListener('input', syncFile);\n    clearFile.addEventListener('click', function () { fileInput.value = ''; syncFile(); });\n    ['dragenter', 'dragover'].forEach(function (t) { drop.addEventListener(t, function () { drop.classList.add('drag'); }); });\n    ['dragleave', 'drop'].forEach(function (t) { drop.addEventListener(t, function () { drop.classList.remove('drag'); }); });\n\n    byId('lib-bump').addEventListener('click', function () {\n        var el = byId('lib-version'); var m = el.value.trim().match(/^(.*?)(\\d+)$/);\n        el.value = m ? m[1] + (Number(m[2]) + 1) : '1.1';\n    });\n\n    var form = byId('lib-form'), button = byId('lib-submit'), result = byId('lib-result');\n    form.addEventListener('submit', function (e) {\n        e.preventDefault();\n        if (button.disabled) return;\n        var file = byId('lib-file').files[0];\n        var url = byId('lib-url').value.trim();\n        var version = byId('lib-version').value.trim();\n        result.textContent = '';\n        if (file) url = ''; // File wins: the link is ignored.\n        if (!validVersion(version)) return say(result, 'Enter a version like 1.3.');\n        if (!file && !url) return say(result, 'Choose a file or enter an https:// link.');\n        if (url && !validUrl(url)) return say(result, 'The link must be a full https:// address (http:// is not allowed).');\n        if (file && file.size > MAX) return say(result, 'The file is larger than {{maxUploadMb}} MB. Use an external link instead.');\n        if (file && file.size < 4) return say(result, 'The selected file is empty.');\n        busy(button, true, 'Publishing…');\n        progress(1, 'Reading file…');\n        var prepare = file ? readBase64(file, function (f) { progress(1 + f * 19, 'Reading file…'); }) : Promise.resolve('');\n        prepare.then(function (b64) {\n            progress(20, file ? 'Uploading ' + bytes(file.size) + '…' : 'Saving link…');\n            return send({\n                action: 'upload', version: version, notes: byId('lib-notes').value.trim(), external_url: url,\n                file_name: file ? file.name : '', content_base64: b64\n            }, function (loaded, total) { progress(20 + (loaded / total) * 75, 'Uploading… ' + bytes(loaded) + ' of ' + bytes(total)); });\n        }).then(function (data) {\n            progress(100, 'Published', 'done');\n            say(result, 'Version ' + data.version + ' is live. Reloading…', true);\n            setTimeout(function () { location.reload(); }, 1200);\n        }).catch(function (err) {\n            progress(100, 'Failed', 'error');\n            say(result, (err && err.message ? err.message : 'Publishing failed.') + ' The previous version is still active.');\n            busy(button, false);\n        });\n    });\n\n})();\n</script>\n","login":"<!doctype html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"utf-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n    <meta name=\"theme-color\" content=\"#000000\">\n    <meta name=\"color-scheme\" content=\"dark\">\n    <meta name=\"robots\" content=\"noindex\">\n    <link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\">\n    <link rel=\"preload\" href=\"/assets/fonts/inter-latin-wght-normal.woff2\" as=\"font\" type=\"font/woff2\" crossorigin>\n    <title>Sign In · {{brand}}</title>\n    <link rel=\"stylesheet\" href=\"/assets/css/ui.css\">\n</head>\n<body class=\"auth\">\n<main class=\"auth-shell\">\n    <div class=\"auth-panel fade-in\">\n        <div class=\"auth-wordmark\">{{brand}} <small>Panel</small></div>\n        <div class=\"auth-card\">\n            <div class=\"tile tile-lg\">{{icon \"shield-check\"}}</div>\n            <h1 class=\"auth-title\">Sign In</h1>\n            <p class=\"lead\">Welcome back. Use your panel account to continue.</p>\n\n            {{> msgStatus}}\n\n            <form method=\"post\" action=\"/login\" class=\"form\" novalidate data-busy-form>\n                <div class=\"field {{#if errors.username}}invalid{{/if}}\">\n                    <label class=\"label\" for=\"username\">Username</label>\n                    <div class=\"input-wrap\">\n                        {{icon \"user\" \"lead\"}}\n                        <input class=\"input\" type=\"text\" name=\"username\" id=\"username\" value=\"{{old.username}}\"\n                               autocomplete=\"username\" autocapitalize=\"none\" spellcheck=\"false\" required minlength=\"3\" maxlength=\"25\"\n                               placeholder=\"Your username\" {{#unless old.username}}autofocus{{/unless}}>\n                    </div>\n                    {{#if errors.username}}<div class=\"error\">{{icon \"circle-alert\"}}<span>{{errors.username}}</span></div>{{/if}}\n                </div>\n                <div class=\"field {{#if errors.password}}invalid{{/if}}\">\n                    <label class=\"label\" for=\"password\">Password</label>\n                    <div class=\"input-wrap has-trail\">\n                        {{icon \"lock\" \"lead\"}}\n                        <input class=\"input\" type=\"password\" name=\"password\" id=\"password\" autocomplete=\"current-password\"\n                               required minlength=\"6\" maxlength=\"45\" placeholder=\"Your password\" {{#if old.username}}autofocus{{/if}}>\n                        <div class=\"trail\">\n                            <button type=\"button\" class=\"icon-btn\" data-toggle-password=\"password\" aria-label=\"Show password\" aria-pressed=\"false\">{{icon \"eye\" \"when-off\"}}{{icon \"eye-off\" \"when-on\"}}</button>\n                        </div>\n                    </div>\n                    {{#if errors.password}}<div class=\"error\">{{icon \"circle-alert\"}}<span>{{errors.password}}</span></div>{{/if}}\n                </div>\n                <label class=\"check\"><input type=\"checkbox\" name=\"stay_log\" id=\"stay_log\" value=\"yes\"> Keep me signed in</label>\n                <button type=\"submit\" class=\"btn btn-primary btn-block btn-lg\" data-busy-label=\"Signing in…\">Sign In {{icon \"arrow-right\"}}</button>\n            </form>\n        </div>\n\n        <div class=\"auth-foot\">\n            <span>Have a referral code? <a href=\"/register\">{{icon \"user-plus\" \"i-sm\"}}Create an account</a></span>\n            <a href=\"{{telegram.url}}\" target=\"_blank\" rel=\"noopener\">{{icon \"send\" \"i-sm\"}}Support {{telegram.handle}}</a>\n        </div>\n    </div>\n</main>\n<script src=\"/assets/js/app-ui.js\"></script>\n</body>\n</html>\n","msgStatus":"{{#if flash.danger}}\n<div class=\"alert alert-danger\" role=\"alert\">{{icon \"circle-alert\"}}<p>{{flash.danger}}</p><button type=\"button\" class=\"alert-close\" data-dismiss aria-label=\"Dismiss\">{{icon \"x\" \"i-sm\"}}</button></div>\n{{else}}{{#if flash.success}}\n<div class=\"alert alert-success\" role=\"status\" data-flash=\"success\">{{icon \"circle-check\"}}<p>{{flash.success}}</p><button type=\"button\" class=\"alert-close\" data-dismiss aria-label=\"Dismiss\">{{icon \"x\" \"i-sm\"}}</button></div>\n{{else}}{{#if flash.warning}}\n<div class=\"alert alert-warning\" role=\"alert\">{{icon \"triangle-alert\"}}<p>{{flash.warning}}</p><button type=\"button\" class=\"alert-close\" data-dismiss aria-label=\"Dismiss\">{{icon \"x\" \"i-sm\"}}</button></div>\n{{else}}{{#if pageMessage}}\n<div class=\"alert {{alertClass pageMessage.type}}\" role=\"status\">{{icon \"info\"}}<p>{{pageMessage.text}}</p><button type=\"button\" class=\"alert-close\" data-dismiss aria-label=\"Dismiss\">{{icon \"x\" \"i-sm\"}}</button></div>\n{{/if}}{{/if}}{{/if}}{{/if}}\n","register":"<!doctype html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"utf-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n    <meta name=\"theme-color\" content=\"#000000\">\n    <meta name=\"color-scheme\" content=\"dark\">\n    <meta name=\"robots\" content=\"noindex\">\n    <link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\">\n    <link rel=\"preload\" href=\"/assets/fonts/inter-latin-wght-normal.woff2\" as=\"font\" type=\"font/woff2\" crossorigin>\n    <title>Create account · {{brand}}</title>\n    <link rel=\"stylesheet\" href=\"/assets/css/ui.css\">\n</head>\n<body class=\"auth\">\n<main class=\"auth-shell\">\n    <div class=\"auth-panel fade-in\">\n        <div class=\"auth-wordmark\">{{brand}} <small>Panel</small></div>\n        <div class=\"auth-card\">\n            <div class=\"tile tile-lg\">{{icon \"user-plus\"}}</div>\n            <h1 class=\"auth-title\">Create account</h1>\n            <p class=\"lead\">You need a referral code from an admin.</p>\n\n            {{> msgStatus}}\n\n            <form method=\"post\" action=\"/register\" class=\"form\" novalidate data-busy-form>\n                <div class=\"field {{#if errors.referral}}invalid{{/if}}\">\n                    <label class=\"label\" for=\"referral\">Referral code</label>\n                    <div class=\"input-wrap\">\n                        {{icon \"ticket\" \"lead\"}}\n                        <input class=\"input mono upper\" type=\"text\" name=\"referral\" id=\"referral\" value=\"{{old.referral}}\"\n                               autocomplete=\"off\" autocapitalize=\"characters\" spellcheck=\"false\" required maxlength=\"25\" placeholder=\"ABC1234\">\n                    </div>\n                    {{#if errors.referral}}<div class=\"error\">{{icon \"circle-alert\"}}<span>{{errors.referral}}</span></div>{{/if}}\n                </div>\n                <div class=\"field {{#if errors.email}}invalid{{/if}}\">\n                    <label class=\"label\" for=\"email\">Email</label>\n                    <div class=\"input-wrap\">\n                        {{icon \"mail\" \"lead\"}}\n                        <input class=\"input\" type=\"email\" name=\"email\" id=\"email\" value=\"{{old.email}}\" autocomplete=\"email\" required maxlength=\"40\" placeholder=\"you@example.com\">\n                    </div>\n                    {{#if errors.email}}<div class=\"error\">{{icon \"circle-alert\"}}<span>{{errors.email}}</span></div>{{/if}}\n                </div>\n                <div class=\"field-row\">\n                    <div class=\"field {{#if errors.username}}invalid{{/if}}\">\n                        <label class=\"label\" for=\"username\">Username</label>\n                        <div class=\"input-wrap\">\n                            {{icon \"at-sign\" \"lead\"}}\n                            <input class=\"input\" type=\"text\" name=\"username\" id=\"username\" value=\"{{old.username}}\" autocomplete=\"username\"\n                                   autocapitalize=\"none\" spellcheck=\"false\" required minlength=\"4\" maxlength=\"25\" placeholder=\"Letters, numbers\">\n                        </div>\n                        {{#if errors.username}}<div class=\"error\">{{icon \"circle-alert\"}}<span>{{errors.username}}</span></div>{{/if}}\n                    </div>\n                    <div class=\"field {{#if errors.fullname}}invalid{{/if}}\">\n                        <label class=\"label\" for=\"fullname\">Name</label>\n                        <div class=\"input-wrap\">\n                            {{icon \"user\" \"lead\"}}\n                            <input class=\"input\" type=\"text\" name=\"fullname\" id=\"fullname\" value=\"{{old.fullname}}\" autocomplete=\"name\" required maxlength=\"40\" placeholder=\"Your name\">\n                        </div>\n                        {{#if errors.fullname}}<div class=\"error\">{{icon \"circle-alert\"}}<span>{{errors.fullname}}</span></div>{{/if}}\n                    </div>\n                </div>\n                <div class=\"hint\" style=\"margin-top:-8px\">Your keys will start with your username, in capitals.</div>\n                <div class=\"field {{#if errors.password}}invalid{{/if}}\">\n                    <label class=\"label\" for=\"password\">Password</label>\n                    <div class=\"input-wrap has-trail\">\n                        {{icon \"lock\" \"lead\"}}\n                        <input class=\"input\" type=\"password\" name=\"password\" id=\"password\" autocomplete=\"new-password\" required minlength=\"6\" maxlength=\"45\" placeholder=\"At least 6 characters\">\n                        <div class=\"trail\">\n                            <button type=\"button\" class=\"icon-btn\" data-toggle-password=\"password\" aria-label=\"Show password\" aria-pressed=\"false\">{{icon \"eye\" \"when-off\"}}{{icon \"eye-off\" \"when-on\"}}</button>\n                        </div>\n                    </div>\n                    {{#if errors.password}}<div class=\"error\">{{icon \"circle-alert\"}}<span>{{errors.password}}</span></div>{{/if}}\n                </div>\n                <div class=\"field {{#if errors.password2}}invalid{{/if}}\">\n                    <label class=\"label\" for=\"password2\">Confirm password</label>\n                    <div class=\"input-wrap\">\n                        {{icon \"lock\" \"lead\"}}\n                        <input class=\"input\" type=\"password\" name=\"password2\" id=\"password2\" autocomplete=\"new-password\" required minlength=\"6\" maxlength=\"45\" placeholder=\"Repeat password\">\n                    </div>\n                    {{#if errors.password2}}<div class=\"error\">{{icon \"circle-alert\"}}<span>{{errors.password2}}</span></div>{{/if}}\n                </div>\n                <button type=\"submit\" class=\"btn btn-primary btn-block btn-lg\" data-busy-label=\"Creating account…\">Create account {{icon \"arrow-right\"}}</button>\n            </form>\n        </div>\n\n        <div class=\"auth-foot\">\n            <span>Already have an account? <a href=\"/login\">Sign in</a></span>\n        </div>\n    </div>\n</main>\n<script src=\"/assets/js/app-ui.js\"></script>\n</body>\n</html>\n","server":"<div class=\"page-head\">\n    <div>\n        <h1 class=\"page-title\">Server</h1>\n        <p class=\"page-sub\">What the loader shows after a successful sign-in.</p>\n    </div>\n</div>\n\n{{> msgStatus}}\n\n<div class=\"grid-2\">\n    <div class=\"stack\">\n        <section class=\"card\">\n            <div class=\"card-head\">\n                <div class=\"tile orange\">{{icon \"power\"}}</div>\n                <div><h2 class=\"card-title\">Maintenance</h2><div class=\"card-sub\">While on, every licence check is refused with your message.</div></div>\n            </div>\n            <form method=\"post\" action=\"/server\" class=\"form\" data-busy-form>\n                <input type=\"hidden\" name=\"status_form\" value=\"1\">\n                <div class=\"switch-list\">\n                    <label class=\"switch\"><span>Maintenance mode</span><input type=\"checkbox\" name=\"radios\" value=\"on\" {{#if (eq onoff.status \"on\")}}checked{{/if}}><span class=\"track\"></span></label>\n                </div>\n                <div class=\"field\">\n                    <label class=\"label\" for=\"myInput\">Message</label>\n                    <textarea class=\"input\" name=\"myInput\" id=\"myInput\" rows=\"3\" maxlength=\"500\" placeholder=\"Server is under maintenance. Please try again later.\">{{onoff.myinput}}</textarea>\n                </div>\n                <div><button type=\"submit\" class=\"btn btn-primary\" data-busy-label=\"Saving…\">{{icon \"check\"}}Save</button></div>\n            </form>\n        </section>\n\n        <section class=\"card\">\n            <div class=\"card-head\">\n                <div class=\"tile\">{{icon \"gamepad-2\"}}</div>\n                <div><h2 class=\"card-title\">Mod name</h2><div class=\"card-sub\">Shown at the top of the mod menu</div></div>\n            </div>\n            <form method=\"post\" action=\"/server\" class=\"form\" data-busy-form>\n                <input type=\"hidden\" name=\"modname_form\" value=\"1\">\n                <div class=\"field\">\n                    <label class=\"label\" for=\"modname\">Name</label>\n                    <div class=\"input-wrap\">{{icon \"pencil\" \"lead\"}}\n                    <input type=\"text\" class=\"input\" name=\"modname\" id=\"modname\" value=\"{{server.modname}}\" required maxlength=\"100\" placeholder=\"Mod name\"></div>\n                </div>\n                <div><button type=\"submit\" class=\"btn btn-primary\" data-busy-label=\"Saving…\">{{icon \"check\"}}Save name</button></div>\n            </form>\n        </section>\n    </div>\n\n    <div class=\"stack\">\n        <section class=\"card\">\n            <div class=\"card-head\">\n                <div class=\"tile green\">{{icon \"shield-check\"}}</div>\n                <div><h2 class=\"card-title\">Mod status</h2><div class=\"card-sub\">Off shows a high-risk warning in the loader.</div></div>\n            </div>\n            <form method=\"post\" action=\"/server\" class=\"form\" data-busy-form>\n                <input type=\"hidden\" name=\"floating_form\" value=\"1\">\n                <div class=\"switch-list\">\n                    <label class=\"switch\"><span>Safe</span><input type=\"checkbox\" name=\"_ftextr\" value=\"Safe\" {{#if (eq ftext._status \"Safe\")}}checked{{/if}}><span class=\"track\"></span></label>\n                </div>\n                <div class=\"field\">\n                    <label class=\"label\" for=\"_ftext\">Floating text</label>\n                    <div class=\"input-wrap\">{{icon \"sparkles\" \"lead\"}}\n                    <input type=\"text\" class=\"input\" name=\"_ftext\" id=\"_ftext\" value=\"{{ftext._ftext}}\" required maxlength=\"100\" placeholder=\"Short status line\"></div>\n                </div>\n                <div><button type=\"submit\" class=\"btn btn-primary\" data-busy-label=\"Saving…\">{{icon \"check\"}}Save status</button></div>\n            </form>\n        </section>\n\n        {{#if user.isOwner}}\n        <section class=\"card\">\n            <div class=\"card-head\">\n                <div class=\"tile purple\">{{icon \"layers\"}}</div>\n                <div><h2 class=\"card-title\">Features</h2><div class=\"card-sub\">Turn mod features on or off for everyone</div></div>\n            </div>\n            <form method=\"post\" action=\"/server\" class=\"form\" data-busy-form>\n                <input type=\"hidden\" name=\"feature_form\" value=\"1\">\n                <div class=\"switch-list\">\n                    <label class=\"switch\"><span>ESP</span><input type=\"checkbox\" name=\"ESP\" value=\"on\" {{#if (eq feature.esp \"on\")}}checked{{/if}}><span class=\"track\"></span></label>\n                    <label class=\"switch\"><span>Items</span><input type=\"checkbox\" name=\"Item\" value=\"on\" {{#if (eq feature.item \"on\")}}checked{{/if}}><span class=\"track\"></span></label>\n                    <label class=\"switch\"><span>Aim-bot</span><input type=\"checkbox\" name=\"AIM\" value=\"on\" {{#if (eq feature.aim \"on\")}}checked{{/if}}><span class=\"track\"></span></label>\n                    <label class=\"switch\"><span>Silent aim</span><input type=\"checkbox\" name=\"SilentAim\" value=\"on\" {{#if (eq feature.silentaim \"on\")}}checked{{/if}}><span class=\"track\"></span></label>\n                    <label class=\"switch\"><span>Bullet track</span><input type=\"checkbox\" name=\"BulletTrack\" value=\"on\" {{#if (eq feature.bullettrack \"on\")}}checked{{/if}}><span class=\"track\"></span></label>\n                    <label class=\"switch\"><span>Memory</span><input type=\"checkbox\" name=\"Memory\" value=\"on\" {{#if (eq feature.memory \"on\")}}checked{{/if}}><span class=\"track\"></span></label>\n                    <label class=\"switch\"><span>Floating text</span><input type=\"checkbox\" name=\"Floating\" value=\"on\" {{#if (eq feature.floating \"on\")}}checked{{/if}}><span class=\"track\"></span></label>\n                    <label class=\"switch\"><span>In-app settings</span><input type=\"checkbox\" name=\"Setting\" value=\"on\" {{#if (eq feature.setting \"on\")}}checked{{/if}}><span class=\"track\"></span></label>\n                </div>\n                <div><button type=\"submit\" class=\"btn btn-primary\" data-busy-label=\"Saving…\">{{icon \"check\"}}Save features</button></div>\n            </form>\n        </section>\n        {{/if}}\n    </div>\n</div>\n","settings":"<div class=\"page-head\">\n    <div>\n        <h1 class=\"page-title\">Settings</h1>\n        <p class=\"page-sub\">Your account and sign-in details.</p>\n    </div>\n    <div class=\"page-actions\">\n        <a href=\"/logout\" class=\"btn btn-danger\">{{icon \"log-out\"}}Sign out</a>\n    </div>\n</div>\n\n{{> msgStatus}}\n\n<div class=\"grid-2\">\n    <div class=\"stack\">\n        <section class=\"card\">\n            <div class=\"card-head\">\n                <div class=\"avatar\" aria-hidden=\"true\" style=\"width:46px;height:46px;flex-basis:46px;font-size:18px\">{{initial user.fullname user.username}}</div>\n                <div><h2 class=\"card-title\">{{user.displayName}}</h2><div class=\"card-sub\">{{user.email}}</div></div>\n            </div>\n            <div class=\"list\">\n                <div class=\"list-row\"><span class=\"lr-label\">{{icon \"at-sign\" \"i-sm\"}}Username</span><span class=\"lr-value\">{{user.username}}</span></div>\n                <div class=\"list-row\"><span class=\"lr-label\">{{icon \"mail\" \"i-sm\"}}Email</span><span class=\"lr-value\">{{user.email}}</span></div>\n                <div class=\"list-row\"><span class=\"lr-label\">{{icon \"shield\" \"i-sm\"}}Role</span><span class=\"lr-value\">{{user.levelName}}</span></div>\n                <div class=\"list-row\"><span class=\"lr-label\">{{icon \"wallet\" \"i-sm\"}}Balance</span><span class=\"lr-value\">{{#if unlimited}}Unlimited{{else}}₹{{user.saldoLabel}}{{/if}}</span></div>\n                <div class=\"list-row\"><span class=\"lr-label\">{{icon \"clock\" \"i-sm\"}}Signed in</span><span class=\"lr-value\">{{sessionSince}}</span></div>\n                <div class=\"list-row\"><span class=\"lr-label\">{{icon \"hourglass\" \"i-sm\"}}Session ends</span><span class=\"lr-value\">{{sessionRemaining}}</span></div>\n            </div>\n        </section>\n\n        <section class=\"card\">\n            <div class=\"card-head\">\n                <div class=\"tile purple\">{{icon \"id-card\"}}</div>\n                <div><h2 class=\"card-title\">Display name</h2><div class=\"card-sub\">Shown in the panel</div></div>\n            </div>\n            <form method=\"post\" action=\"/settings\" class=\"form\" novalidate data-busy-form>\n                <input type=\"hidden\" name=\"fullname_form\" value=\"1\">\n                <div class=\"field {{#if errors.fullname}}invalid{{/if}}\">\n                    <label class=\"label\" for=\"fullname\">Name</label>\n                    <div class=\"input-wrap\">{{icon \"user\" \"lead\"}}\n                    <input type=\"text\" class=\"input\" name=\"fullname\" id=\"fullname\" value=\"{{form.fullname}}\" required maxlength=\"155\" autocomplete=\"name\"></div>\n                    {{#if errors.fullname}}<div class=\"error\">{{icon \"circle-alert\"}}<span>{{errors.fullname}}</span></div>{{/if}}\n                </div>\n                <div><button type=\"submit\" class=\"btn btn-primary\" data-busy-label=\"Saving…\">{{icon \"check\"}}Save name</button></div>\n            </form>\n        </section>\n    </div>\n\n    <section class=\"card\">\n        <div class=\"card-head\">\n            <div class=\"tile green\">{{icon \"lock\"}}</div>\n            <div><h2 class=\"card-title\">Password</h2><div class=\"card-sub\">Changing it signs out every other session.</div></div>\n        </div>\n        <form method=\"post\" action=\"/settings\" class=\"form\" novalidate data-busy-form>\n            <input type=\"hidden\" name=\"password_form\" value=\"1\">\n            <div class=\"field {{#if errors.current}}invalid{{/if}}\">\n                <label class=\"label\" for=\"current\">Current password</label>\n                <div class=\"input-wrap has-trail\">{{icon \"lock\" \"lead\"}}\n                <input type=\"password\" class=\"input\" name=\"current\" id=\"current\" required autocomplete=\"current-password\" maxlength=\"45\">\n                <div class=\"trail\"><button type=\"button\" class=\"icon-btn\" data-toggle-password=\"current\" aria-label=\"Show password\" aria-pressed=\"false\">{{icon \"eye\" \"when-off\"}}{{icon \"eye-off\" \"when-on\"}}</button></div></div>\n                {{#if errors.current}}<div class=\"error\">{{icon \"circle-alert\"}}<span>{{errors.current}}</span></div>{{/if}}\n            </div>\n            <div class=\"field {{#if errors.password}}invalid{{/if}}\">\n                <label class=\"label\" for=\"password\">New password</label>\n                <div class=\"input-wrap has-trail\">{{icon \"key-round\" \"lead\"}}\n                <input type=\"password\" class=\"input\" name=\"password\" id=\"password\" required minlength=\"6\" maxlength=\"45\" autocomplete=\"new-password\">\n                <div class=\"trail\"><button type=\"button\" class=\"icon-btn\" data-toggle-password=\"password\" aria-label=\"Show password\" aria-pressed=\"false\">{{icon \"eye\" \"when-off\"}}{{icon \"eye-off\" \"when-on\"}}</button></div></div>\n                {{#if errors.password}}<div class=\"error\">{{icon \"circle-alert\"}}<span>{{errors.password}}</span></div>{{/if}}\n            </div>\n            <div class=\"field {{#if errors.password2}}invalid{{/if}}\">\n                <label class=\"label\" for=\"password2\">Confirm new password</label>\n                <div class=\"input-wrap\">{{icon \"key-round\" \"lead\"}}\n                <input type=\"password\" class=\"input\" name=\"password2\" id=\"password2\" required minlength=\"6\" maxlength=\"45\" autocomplete=\"new-password\"></div>\n                {{#if errors.password2}}<div class=\"error\">{{icon \"circle-alert\"}}<span>{{errors.password2}}</span></div>{{/if}}\n            </div>\n            <div><button type=\"submit\" class=\"btn btn-primary\" data-busy-label=\"Saving…\">{{icon \"shield-check\"}}Change password</button></div>\n        </form>\n    </section>\n</div>\n"};
